import json

def read_user_assistant_pairs(fpath, max_pairs=10):
    pairs = []
    curr_user = ""
    with open(fpath, "r", encoding="utf-8", errors="ignore") as f:
        for line in f:
            try:
                rec = json.loads(line)
            except Exception:
                continue
            t = rec.get("type")
            if t == "user":
                msg = rec.get("message", {})
                c = msg.get("content")
                if isinstance(c, str):
                    curr_user = c
                elif isinstance(c, list):
                    curr_user = "".join(x.get("text", "") for x in c if isinstance(x, dict) and x.get("type") == "text")
            elif t == "assistant" and curr_user:
                msg = rec.get("message", {})
                c = msg.get("content", [])
                asst_text = ""
                for x in c:
                    if isinstance(x, dict) and x.get("type") == "text":
                        asst_text += x.get("text", "")
                if asst_text and not curr_user.startswith("<user_preferences>"):
                    pairs.append((curr_user[:150], asst_text[:500]))
                curr_user = ""
    return pairs

