7	SafetyWatchdog::SafetyWatchdog(WatchdogConfig config) : config_(std::move(config)) {}
8	
9	void SafetyWatchdog::FeedHeartbeat(const std::string& node) {
10	  last_seen_[node] = std::chrono::steady_clock::now();
11	}
