17	std::vector<SafetyEvent> SafetyWatchdog::Inspect(
18	    const std::vector<std::string>& watched_nodes) const {
19	  std::vector<SafetyEvent> events;
20	  const auto now = std::chrono::steady_clock::now();
21	  for (const auto& node : watched_nodes) {
22	    auto it = last_seen_.find(node);
23	    if (it == last_seen_.end()) {
24	      SafetyEvent e;
25	      e.source = "watchdog/" + node;
26	      e.severity = SafetySeverity::kCritical;
