135	  if (!watchdog_ || !gate_ || !fault_supervisor_) return;
136	
137	  auto events = watchdog_->Inspect(watched_nodes_);
138	  watchdog_ok_ = events.empty();
139	  for (auto& ev : events) {
140	    gate_->PushEvent(ev);
141	    RCLCPP_WARN_THROTTLE(get_logger(), *get_clock(), 1000,
142	                         "Watchdog event: source=%s msg=%s", ev.source.c_str(), ev.message.c_str());
143	  }
144	
145	  // 聚合四大防御源至 Fault Supervisor Engine
146	  amr_dispatcher_core::safety::MultiSourceHealthReport report;
147	  report.chassis_healthy = chassis_healthy_;
148	  report.chassis_loss_rate = chassis_loss_rate_;
149	  report.watchdog_healthy = watchdog_ok_;
150	  report.deadlock_detected = deadlock_active_;
151	  report.manual_estop = estop_active_ || bumper_active_;
152	  report.detail_message = watchdog_ok_ ? (chassis_healthy_ ? "healthy" : "chassis degraded") : "watchdog timeout";
153	
154	  fault_supervisor_->UpdateMultiSourceHealth(report);
155	  fault_supervisor_->Tick();
156	
157	  // 根据 Fault Supervisor 综合裁决建议执行动作
158	  auto rec = fault_supervisor_->recommendation();
159	  if (rec == amr_dispatcher_core::safety::SystemActionRecommendation::kEmergencyStop) {
160	    auto_fault_latched_ = true;
161	  } else if (rec == amr_dispatcher_core::safety::SystemActionRecommendation::kNone && auto_fault_latched_) {
162	    // 故障恢复且自动清除模式下解除自动急停锁存（若非人工急停按钮触发）
163	    auto_fault_latched_ = false;
164	  }
165	
166	  // 空闲周期播报安全状态：无 cmd_vel 上游时也要让 /safety/state 持续可见，
167	  // 否则 lifecycle_coordinator 的 safety_seen_ 永为 false，/system/ready 卡 INITIALIZING。
168	  PublishIdleSafetyState();
169	}
