72	  current_pose_.x = msg->pose.pose.position.x;
73	  current_pose_.y = msg->pose.pose.position.y;
74	  current_pose_.yaw = amr_dispatcher_core::path_tracking::YawFromQuaternion(
75	      msg->pose.pose.orientation.z, msg->pose.pose.orientation.w);
76	  current_linear_speed_ = msg->twist.twist.linear.x;
77	  has_odom_ = true;
78	}
