  const res = parseFloat(document.getElementById('mapResInput').value) || 0.05;
  const ox = parseFloat(document.getElementById('mapOriginXInput').value) || 0.0;
  const oy = parseFloat(document.getElementById('mapOriginYInput').value) || 0.0;
  const baseUrl = baseUrlInput.value.replace(/\/$/, '');

  const payload = {
    width: mapWidth,
    height: mapHeight,
    resolution: res,
    origin_x: ox,
    origin_y: oy,
    grid_data: gridData,
    anchors: anchors.map(a => ({
      id: a.id,
      type: a.type,
      x: a.x,
      y: a.y,
      yaw: a.yaw
    }))
  };

  try {
    setStatus("🚀 正在生成骨架路网并原子重载调度拓扑...", true);
    uploadMapBtn.disabled = true;
    uploadMapBtn.textContent = "⏳ 正在提取拓扑...";

    const resp = await fetch(`${baseUrl}/api/v1/map/upload`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(payload)
    });
    const result = await resp.json();

    if (resp.ok && result.status === 'ok') {
      setStatus(`🎉 地图路网热重载成功! 生成 ${result.stations_count} 站点, ${result.road_nodes_count} 通行路口, ${result.edges_count} 拓扑边`, true);
      alert(`✅ 地图拓扑生成成功并生效！\n站点: ${result.stations_count} 个\n通行路口: ${result.road_nodes_count} 个\n拓扑折线边: ${result.edges_count} 条\n版本Hash: ${result.map_hash}`);
      fetchSnapshot();
    } else {
      setStatus(`❌ 地图导入失败: ${result.message || result.error}`, false);
      alert(`❌ 地图导入失败: ${result.message || result.error}`);
    }
  } catch (err) {
    setStatus(`网络错误: ${err.message}`, false);
    alert(`请求失败: ${err.message}`);
  } finally {
    uploadMapBtn.disabled = false;
    uploadMapBtn.textContent = "🚀 一键生成路网并热重载";
  }
});

