// 地图版本门禁：非空时要求 catalog.map_hash 与之相等，否则暂停出队派发
std::string expected_map_hash_;
// 版本门禁状态（每次 ScheduleTick 重算；false = 地图哈希不匹配，派发已暂停）
bool map_version_valid_{true};
