46	CallbackReturn DispatcherNode::on_configure(const rclcpp_lifecycle::State& /*state*/) {
47	  const std::size_t cap = get_parameter("queue_capacity").as_int();
48	  const std::string comp_name = get_parameter("comparator").as_string();
49	
50	  queue_ = std::make_unique<amr_dispatcher_core::dispatcher::MissionQueue>(
51	      amr_dispatcher_core::dispatcher::MissionQueue::Config{cap, comp_name});
52	  reservation_table_ = std::make_unique<amr_dispatcher_core::dispatcher::TrafficReservationTable>();
53	  event_log_ = std::make_unique<amr_dispatcher_core::dispatcher::MissionEventLog>(256);
54	  deadlock_detector_ = std::make_unique<amr_dispatcher_core::dispatcher::DeadlockDetector>(
55	      amr_dispatcher_core::dispatcher::DeadlockDetectorConfig{
56	          static_cast<std::size_t>(get_parameter("max_active_missions").as_int()),
57	          10s, 30s});
58	  recovery_policy_ = std::make_unique<amr_dispatcher_core::dispatcher::RecoveryPolicy>();
59	
60	  // 站点目录与基准线性规划器：任务激活时把 pickup→dropoff 展开成 /plan 下发。
61	  // 目录经 StationCatalogReloader 持有：构造时加载，mtime 变化自动热重载；
62	  // 初始加载失败也照常挂监听，文件补齐后下一个 Tick 即生效。
63	  const std::string stations_file = get_parameter("stations_file").as_string();
64	  catalog_reloader_ =
65	      std::make_unique<amr_dispatcher_core::catalog::StationCatalogReloader>(stations_file);
66	  if (catalog_reloader_->loaded()) {
67	    RCLCPP_INFO(get_logger(), "Loaded %zu stations from %s",
68	                catalog_reloader_->catalog().stations.size(), stations_file.c_str());
69	  } else {
70	    RCLCPP_WARN(get_logger(),
71	                "Failed to load stations file %s; planning disabled until hot reload succeeds",
72	                stations_file.c_str());
73	  }
74	  // 依 planner_type 选规划器：skeleton -> 混合图折线循迹，mock -> 直线基线。
75	  // catalog_reloader_ 已就位（即使初始加载失败也持有空目录，热重载后由 reload_timer_ 同步）。
76	  RebuildPlanner();
77	
78	  state_pub_ = create_publisher<amr_dispatcher_interfaces::msg::DispatcherState>(
79	      "/dispatcher/state", 10);
80	  event_pub_ = create_publisher<amr_dispatcher_interfaces::msg::MissionEvent>(
81	      "/dispatcher/events", 20);
82	  plan_pub_ = create_publisher<nav_msgs::msg::Path>("/plan", 1);
83	  // 拓扑状态：safety_gate（deadlock_active_）与 visualizer（绿锁边/红警戒柱）的死锁输入
84	  topology_pub_ = create_publisher<amr_dispatcher_interfaces::msg::TopologyState>(
85	      "/dispatcher/topology_state", 10);
86	
87	  // 位姿与到达信号订阅：path_tracker 的 TrackingError.arrived 驱动任务完成
88	  odom_sub_ = create_subscription<nav_msgs::msg::Odometry>(
89	      "/odom", 10, std::bind(&DispatcherNode::OdomCb, this, std::placeholders::_1));
90	  tracking_error_sub_ = create_subscription<amr_dispatcher_interfaces::msg::TrackingError>(
91	      "/tracking/error", 10,
92	      std::bind(&DispatcherNode::TrackingErrorCb, this, std::placeholders::_1));
93	
94	  // Task 5：VDA 5050 状态/链路接入（逐段解锁 + 断链守卫），按参数建订阅
95	  SetupVda5050Links(get_parameter("vda5050_vehicles").as_string());
96	
97	  submit_srv_ = create_service<amr_dispatcher_interfaces::srv::SubmitOrder>(
98	      "/dispatcher/submit_order",
99	      std::bind(&DispatcherNode::SubmitOrderCb, this, std::placeholders::_1, std::placeholders::_2));
100	  cancel_srv_ = create_service<amr_dispatcher_interfaces::srv::CancelOrder>(
101	      "/dispatcher/cancel_order",
102	      std::bind(&DispatcherNode::CancelOrderCb, this, std::placeholders::_1, std::placeholders::_2));
103	  pause_srv_ = create_service<amr_dispatcher_interfaces::srv::PauseMission>(
104	      "/dispatcher/pause_mission",
105	      std::bind(&DispatcherNode::PauseMissionCb, this, std::placeholders::_1, std::placeholders::_2));

