641	void DispatcherNode::ForceClearVda5050LinkCb(
642	    const std::shared_ptr<amr_dispatcher_interfaces::srv::ForceClearVda5050Link::Request> req,
643	    std::shared_ptr<amr_dispatcher_interfaces::srv::ForceClearVda5050Link::Response> resp) {
644	  // Task 7（终审 I1 闭合）：仅受理"受管清单内且当前离线"的车辆——在线车辆
645	  // 强清会误杀活车；锁保留/释放决定只在断链语义下才有安全依据。
646	  const auto link_it = vda5050_links_.find(req->vehicle_id);
647	  if (link_it == vda5050_links_.end()) {
648	    resp->success = false;
649	    resp->message = "Vehicle " + req->vehicle_id + " not in managed list";
650	    return;
651	  }
652	  if (link_it->second.online) {
653	    resp->success = false;
654	    resp->message =
655	        "Vehicle " + req->vehicle_id + " is ONLINE — refusing to force-clear a live link";
656	    return;
657	  }
658	
659	  // ---- 1) 锁归属反推：锁 owner 是 mission_id；mission -> 车辆经下发登记反查 ----
660	  // 依据 vda5050_mission_vehicle_（PublishVda5050Order 下发时登记的 mission->vehicle 绑定）。
661	  // 绝不用"路径存档存在"推断归属——那会把其他车辆的 mission 锁误判为该车名下。
662	  std::unordered_map<std::string, std::vector<std::string>> mission_owned_ids;
663	  if (reservation_table_) {
664	    for (const auto& [resource_id, owner] : reservation_table_->Snapshot()) {
665	      const auto bind_it = vda5050_mission_vehicle_.find(owner);
666	      if (bind_it == vda5050_mission_vehicle_.end() || bind_it->second != req->vehicle_id) {
667	        continue;  // 非该车承接的 mission（含 traffic_block 等）-> 保守跳过
668	      }
669	      mission_owned_ids[owner].push_back(resource_id);
670	    }
671	  }
672	
673	  // ---- 2) 释放该车名下锁（先于任务收口，保证 released_resources 可取证）----
674	  std::vector<std::string> released;
675	  if (reservation_table_) {
