2436	void DispatcherNode::Vda5050OnlineCb(const std::string& vehicle_id,
2437	                                     const std_msgs::msg::Bool::SharedPtr msg) {
2438	  auto it = vda5050_links_.find(vehicle_id);
2439	  if (it == vda5050_links_.end()) {
2440	    return;
2441	  }
2442	  if (it->second.online == msg->data) {
2443	    return;  // 状态未变（transient_local 重放/重复报文）：不重复告警
2444	  }
2445	  it->second.online = msg->data;
2446	  if (!msg->data) {
2447	    // Rule 2（Spec §5.2 断链锁定保护）：仅标记离线 + 软看门狗告警，绝不释放任何锁。
2448	    // 锁保留直至该车重连后 state 重核对坐标，或操作员人工强制解除。
2449	    const auto guard = amr_dispatcher_core::workflow::EvaluateVehicleLinkGuard(
2450	        /*vehicle_online=*/false, /*state_stale=*/false);
2451	    RCLCPP_WARN(get_logger(), "VDA 5050 vehicle %s link broken: %s", vehicle_id.c_str(),
2452	                guard.message.c_str());
2453	    if (event_log_) {
2454	      amr_dispatcher_core::dispatcher::MissionEvent evt;
2455	      evt.stamp = "now";
2456	      evt.mission_id = "-";  // 无任务级事件：链路级看门狗告警
2457	      evt.event = "vehicle_offline";
2458	      evt.message = "vehicle " + vehicle_id + ": retaining all route locks pending "
2459	                    "reconnection and position re-verification (Spec 5.2)";
2460	      event_log_->Append(evt);
2461	    }
2462	  } else {
2463	    RCLCPP_INFO(get_logger(),
2464	                "VDA 5050 vehicle %s back online: locks retained until state re-confirms "
2465	                "lastNodeId against the order (Spec 5.2 position re-verification)",
2466	                vehicle_id.c_str());
2467	  }
2468	}
