  const auto d = fleet::PlanVehicleAssignment(req);
  EXPECT_TRUE(d.assigned);
  EXPECT_EQ(d.vehicle_id, "v2");
}

TEST(VehicleAssignmentTest, AutoSelect_BatteryThresholdExcludes) {
