  auto req = MakeRequest("amr_01");
  req.mission_vehicle_bindings = {{"m_1", "amr_01"}, {"m_2", "amr_02"}};
  req.held_locks = {
      {"route_node:A", "m_1"},
      {"route_edge:A__B", "m_1"},
      {"route_node:C", "m_2"},
      {"route_node:D", "traffic_block:reason"},
  };

