function setStatus(msg, ok = true) {
  statusLine.innerHTML = `<span class="dot" style="background:${ok ? 'var(--success)' : 'var(--danger)'}"></span> ${msg}`;
}

async function fetchSnapshot() {
  const baseUrl = baseUrlInput.value.replace(/\/$/, '');
  try {
    const res = await fetch(`${baseUrl}/api/operator/snapshot`);
    if (!res.ok) throw new Error(`HTTP error: ${res.status}`);
    const data = await res.json();
    renderData(data);
    setStatus(`已更新状态: ${new Date().toLocaleTimeString()}`, true);
  } catch (err) {
    setStatus(`连接网关失败: ${err.message}`, false);
  }
}

function renderData(data) {
  eventsPane.textContent = JSON.stringify(data, null, 2);

  // Dispatcher
  document.getElementById('dispStrategy').textContent = data.comparator || data.strategy || 'PriorityFIFO';
  document.getElementById('dispQueueSize').textContent = `${data.queue_size || 0} / ${data.queue_capacity || 256}`;
  document.getElementById('dispActiveCount').textContent = data.active_count || 0;
  document.getElementById('queueBadge').textContent = `${data.queue_size || 0} 待处理`;

  const deadlockEl = document.getElementById('dispDeadlock');
  if (data.deadlock || data.deadlock_detected) {
    deadlockEl.textContent = 'DEADLOCK ALERT!';
    deadlockEl.className = 'pill red';
  } else {
    deadlockEl.textContent = 'NORMAL';
    deadlockEl.className = 'pill green';
  }

  // Safety
  const estopEl = document.getElementById('safetyEstop');
  if (data.estop_active) {
    estopEl.textContent = 'LOCKED (E-STOP)';
    estopEl.className = 'pill red';
  } else {
    estopEl.textContent = 'RELEASED';
    estopEl.className = 'pill green';
  }

  // Locks
  const lockedEdges = data.locked_edges || [];
  document.getElementById('lockedEdges').textContent = lockedEdges.length ? lockedEdges.join(', ') : '无占用';
}

// 提单
document.getElementById('submitOrderBtn').addEventListener('click', async () => {
  const baseUrl = baseUrlInput.value.replace(/\/$/, '');
  const id = document.getElementById('orderId').value;
  const from = document.getElementById('fromStation').value;
  const to = document.getElementById('toStation').value;
  const prio = document.getElementById('orderPrio').value;

  try {
    setStatus(`正在下发任务 ${id}...`);
    const url = `${baseUrl}/api/v1/orders?id=${encodeURIComponent(id)}&from=${encodeURIComponent(from)}&to=${encodeURIComponent(to)}&prio=${prio}`;
    const res = await fetch(url, { method: 'POST' });
    const result = await res.json();
    if (result.status === 'ok') {
      setStatus(`任务 ${id} 提交成功!`, true);
      fetchSnapshot();
    } else {
      setStatus(`提交失败: ${JSON.stringify(result)}`, false);
    }
  } catch (err) {
    setStatus(`提单错误: ${err.message}`, false);
  }
});

