      snap.allocation_graph.held_by[resource_id] = owner_id;
      snap.reserved_resource_ids.insert(resource_id);
    }
  }
  snap.allocation_graph.waiting_for = pending_wait_;
  snap.reservation_acquired_at = mission_reserved_at_;
  return snap;
}

