#pragma once

#include <chrono>
#include <functional>
#include <cstdint>
#include <string>
#include <unordered_map>
#include <vector>

namespace amr_dispatcher_core::workflow {

// 时空窗交通协调（Task B）：把"静态排他锁"升级为"带时间窗的预约"。
//
// 安全模型（评审要求）：
//   1. **逐资源区间**：一条路径涉及多个资源（边=通道、节点=路口），
//      每个资源单独计算进入/离开时刻。路口窗口 = 进入路口到驶出路口的完整区间。
//   2. **全有或全无**：整条路径的预约必须**全部成功**才提交；任一资源失败
//      则全部回滚，不留半套预约。
//   3. **窗口到期 ≠ 资源已释放**：物理资源仍需车辆确认驶离（lastNodeId 推进，
//      见 Spec §5.3 逐段解锁）才可让后车进入。延期靠 ExtendTimeSpace，
//      绝不靠"到点自动失效"。
//   4. **安全余量**：占用时长含加减速/转弯附加时间与车辆尺寸安全余量。
//
// 本模块只做**决策**（纯函数、零 ROS）；预约表的落地由 ResourceTable 承担。

// 单个资源的时间占用区间。
struct ResourceTimeWindow {
  std::string resource_id;   // route_edge:A__B 或 route_node:A
  std::chrono::steady_clock::time_point enter;
  std::chrono::steady_clock::time_point exit;
  // 该资源是"通道"（边）还是"路口"（节点）——路口的冲突判定更严格
  // （对向/交叉车辆的物理冲突发生在路口内部）。
  bool is_intersection = false;
};

// 路径占用区间集合（一个 mission 的全部资源）。
using ResourceTimeWindowSet = std::vector<ResourceTimeWindow>;

// 车辆运动参数（用于把几何长度换算成时间占用）。
struct MotionTimingConfig {
  // 巡航速度（m/s）。
  double cruise_speed_mps = 1.0;
  // 起步/刹停附加时间（秒）——每次进入资源都要付。
  double accel_overhead_sec = 1.0;
  // 转弯附加时间（秒）——按路径拐点数计。
  double turn_overhead_sec = 0.5;
  // 车辆尺寸安全余量（米）——沿路径方向额外占用长度。
  double safety_margin_m = 0.2;
  // 最小安全间隔（秒）：后车进入同一资源前必须与前车拉开该间隔。
  double min_headway_sec = 2.0;
};

// 单个候选任务的输入。
struct TimeSpaceCandidate {
  std::string mission_id;
  // 该单的行驶路径（节点序列，行驶序）。
  std::vector<std::string> path_node_ids;
  // 路径中每段的折线长度（米），与 path_node_ids 的相邻对一一对应：
  // lengths[i] 对应 path_node_ids[i] -> path_node_ids[i+1]。
  std::vector<double> segment_lengths_m;
  // 该单的最早可开始时刻。
  std::chrono::steady_clock::time_point earliest_start;
  // 资源 id 构造器（由调用方注入，核心不直接依赖 dispatcher 层）：
  // 边 id = f(from, to)，节点 id = g(node)。
  std::function<std::string(const std::string&, const std::string&)> edge_id_builder;
  std::function<std::string(const std::string&)> node_id_builder;
  // 期望时长（秒）：优先用它替代按长度估算（业务给的更准）。
  int expected_seconds = 0;
};

// 冲突检测结果（对一次预约尝试）。
struct TimeSpaceConflict {
  bool has_conflict = false;
  std::string resource_id;
  std::string conflicting_mission_id;
  // 冲突原因：headway（安全间隔不足）/ overlap（区间重叠）
  std::string reason;
  // 建议后移的时长（秒）。
  double suggested_delay_sec = 0.0;
};

// 一单的预约决策结果。
struct TimeSpacePlan {
  bool feasible = false;
  std::string reject_reason;
  // 每条资源最终占用的区间（可能整体后移）。
  ResourceTimeWindowSet windows;
  // 整体后移的时长（秒）。
  double total_delay_sec = 0.0;
  // 冲突诊断（供可观测与调度重排）。
  std::vector<TimeSpaceConflict> conflicts;
};

// 已占用区间表：resource_id -> 区间列表（含 mission 与安全间隔）。
struct TimeSpaceOccupancy {
  struct Entry {
    std::string mission_id;
    std::chrono::steady_clock::time_point enter;
    std::chrono::steady_clock::time_point exit;
    bool is_intersection = false;
  };
  std::unordered_map<std::string, std::vector<Entry>> by_resource;
};

// 纯函数：为一个候选任务规划时间窗。
//   1. 按 MotionTimingConfig 把路径换算成逐资源区间（含加减速/转弯/安全余量）。
//   2. 与 occupancy 比对：区间重叠 或 后车进入早于前车离开 + min_headway -> 冲突。
//   3. 冲突时整体后移到最早可行时刻（最多重试 occupancy.size()+1 次），
//      仍冲突 -> feasible=false。
//   4. 成功时返回各资源的最终窗口（调用方负责写回 occupancy）。
TimeSpacePlan PlanTimeSpaceReservation(const TimeSpaceCandidate& candidate,
                                       const TimeSpaceOccupancy& occupancy,
                                       const MotionTimingConfig& config);

// 把一个已确认的时间窗集合并入占用表（调用方在整条路径预约成功后调用）。
void CommitTimeSpaceOccupancy(TimeSpaceOccupancy* occupancy, const std::string& mission_id,
                               const ResourceTimeWindowSet& windows);

// 逐资源释放某任务的占用区间（车辆**确认驶离**该资源后调用）。
//   * 只释放该任务在该资源上的区间（owner 校验），他人区间不动；
//   * 该资源上该任务没有区间 -> 幂等 no-op（返回 false 但不改表）。
// 评审 B.2 的关键：**窗口到期 ≠ 资源已释放**——到期只意味着"计划上应该走了"，
// 物理释放必须由确认驶离驱动，否则后车会在前车还在时进入。
bool ReleaseTimeSpaceResources(TimeSpaceOccupancy* occupancy, const std::string& mission_id,
                               const std::vector<std::string>& resource_ids,
                               std::vector<std::string>* released_resource_ids);

// 某任务在某资源上是否仍持有占用区间。
bool HoldsTimeSpaceResource(const TimeSpaceOccupancy& occupancy, const std::string& mission_id,
                             const std::string& resource_id);

// 车辆执行滞后时延长其占用窗口（评审 B.2：窗口到期不能单独作为释放依据）。
// 延长失败（与后车窗口冲突）时返回 false，由调度层让后车等待。
bool ExtendTimeSpaceOccupancy(TimeSpaceOccupancy* occupancy, const std::string& mission_id,
                               const std::chrono::steady_clock::time_point& new_exit,
                               std::string* message);

}  // namespace amr_dispatcher_core::workflow

#include "amr_dispatcher_core/fleet/vehicle_assignment.hpp"

#include <algorithm>
#include <limits>
#include <string>
#include <vector>

namespace amr_dispatcher_core::fleet {

namespace {

std::string JoinReasons(const std::vector<std::string>& parts) {
  std::string joined;
  for (std::size_t i = 0; i < parts.size(); ++i) {
    if (i) joined += ", ";
    joined += parts[i];
  }
  return joined;
}

}  // namespace

const char* VehicleBackendLabel(VehicleExecutionBackend backend) {
  switch (backend) {
    case VehicleExecutionBackend::kLocalSim:
      return "local_sim";
    case VehicleExecutionBackend::kVda5050:
      return "vda5050";
  }
  return "local_sim";
}

bool ParseVehicleBackend(const std::string& label, VehicleExecutionBackend* out) {
  if (out == nullptr) {
    return false;
  }
  if (label == "local_sim" || label.empty()) {
    *out = VehicleExecutionBackend::kLocalSim;
    return true;
  }
  if (label == "vda5050") {
    *out = VehicleExecutionBackend::kVda5050;
    return true;
  }
  return false;
}

bool VehicleHasCapability(const VehicleRuntimeState& vehicle, const std::string& capability) {
  if (capability.empty()) {
    return true;
  }
  if (vehicle.capabilities.empty()) {
    return true;  // 未声明能力限制
  }
  return std::find(vehicle.capabilities.begin(), vehicle.capabilities.end(), capability) !=
         vehicle.capabilities.end();
}

bool VehicleStateIsFresh(const VehicleRuntimeState& vehicle, int64_t state_max_age_ms) {
  // 从未收到过状态（state_time 为默认构造值）-> 状态不确定，不新鲜
  if (vehicle.state_time == std::chrono::steady_clock::time_point{}) {
    return false;
  }
  const auto age = std::chrono::duration_cast<std::chrono::milliseconds>(
                       std::chrono::steady_clock::now() - vehicle.state_time)
                       .count();
  return age <= state_max_age_ms;
}

VehicleAssignmentDecision PlanVehicleAssignment(const VehicleAssignmentRequest& request) {
  VehicleAssignmentDecision decision;

  if (request.vehicles.empty()) {
    decision.outcome = AssignmentOutcome::kRejected;
    decision.strategy = "rejected";
    decision.reject_reason = "no managed vehicles configured";
    return decision;
  }

  const std::string& capability = request.required_capability;

  // ---- 规则 2：显式指定车辆（点名不豁免硬约束，但豁免位置/新鲜度）----
  if (!request.requested_vehicle_id.empty()) {
    const auto it = std::find_if(
        request.vehicles.begin(), request.vehicles.end(),
        [&](const VehicleRuntimeState& v) { return v.vehicle_id == request.requested_vehicle_id; });
    if (it == request.vehicles.end()) {
      decision.outcome = AssignmentOutcome::kRejected;
      decision.strategy = "rejected";
      decision.reject_reason =
          "vehicle '" + request.requested_vehicle_id + "' is not in the managed vehicle list";
      return decision;
    }
    const auto& vehicle = *it;
    decision.blocking_vehicle_id = vehicle.vehicle_id;
    // 永久不满足（不会自行恢复，需人或运维改配置）-> 拒绝
    if (!vehicle.enabled) {
      decision.outcome = AssignmentOutcome::kRejected;
      decision.strategy = "rejected";
      decision.reject_reason = "vehicle '" + vehicle.vehicle_id + "' is disabled";
      return decision;
    }
    if (!VehicleHasCapability(vehicle, capability)) {
      decision.outcome = AssignmentOutcome::kRejected;
      decision.strategy = "rejected";
      decision.reject_reason = "vehicle '" + vehicle.vehicle_id + "' lacks required capability '" +
                              capability + "'";
      return decision;
    }
    if (vehicle.battery_percent < request.min_battery_percent) {
      decision.outcome = AssignmentOutcome::kRejected;
      decision.strategy = "rejected";
      decision.reject_reason = "vehicle '" + vehicle.vehicle_id + "' battery below threshold";
      return decision;
    }
    // 暂时不可用（会自行恢复）-> 留队等待，不判负
    if (vehicle.quarantined) {
      decision.outcome = AssignmentOutcome::kDeferred;
      decision.strategy = "deferred";
      decision.reject_reason = "vehicle '" + vehicle.vehicle_id +
                              "' is quarantined — restore it before assigning tasks";
      return decision;
    }
    if (!vehicle.online) {
      decision.outcome = AssignmentOutcome::kDeferred;
      decision.strategy = "deferred";
      decision.reject_reason = "vehicle '" + vehicle.vehicle_id + "' is offline";
      return decision;
    }
    if (vehicle.busy) {
      // 车忙是**暂时**状态：任务留队等待该车空闲，不判负
      decision.outcome = AssignmentOutcome::kDeferred;
      decision.strategy = "deferred";
      decision.reject_reason = "vehicle '" + vehicle.vehicle_id + "' is busy";
      return decision;
    }
    decision.outcome = AssignmentOutcome::kAssigned;
    decision.strategy = "explicit";
    decision.vehicle_id = vehicle.vehicle_id;
    return decision;
  }

  // ---- 规则 3：自动选车 ----
  std::vector<const VehicleRuntimeState*> eligible;
  eligible.reserve(request.vehicles.size());
  bool saw_never_seen = false;   // 从未收到状态的车
  bool saw_stale = false;        // 状态超龄的车
  bool saw_busy = false;
  bool saw_offline = false;      // 链路离线（暂时）
  bool saw_quarantined = false;  // 隔离态（暂时，待人工恢复）
  bool saw_no_position = false;
  bool saw_capable = false;
  std::vector<std::string> blockers;

  for (const auto& vehicle : request.vehicles) {
    if (!VehicleHasCapability(vehicle, capability)) {
      continue;
    }
    saw_capable = true;
    if (!vehicle.enabled) {
      blockers.push_back(vehicle.vehicle_id + ":disabled");
      continue;
    }
    if (vehicle.quarantined) {
      saw_quarantined = true;
      blockers.push_back(vehicle.vehicle_id + ":quarantined");
      continue;
    }
    if (!vehicle.online) {
      saw_offline = true;
      blockers.push_back(vehicle.vehicle_id + ":offline");
      continue;
    }
    if (vehicle.busy) {
      saw_busy = true;
      blockers.push_back(vehicle.vehicle_id + ":busy");
      continue;
    }
    if (vehicle.battery_percent < request.min_battery_percent) {
      blockers.push_back(vehicle.vehicle_id + ":battery");
      continue;
    }
    if (vehicle.state_time == std::chrono::steady_clock::time_point{}) {
      saw_never_seen = true;
      blockers.push_back(vehicle.vehicle_id + ":no_state");
      continue;
    }
    if (!VehicleStateIsFresh(vehicle, request.state_max_age_ms)) {
      saw_stale = true;
      blockers.push_back(vehicle.vehicle_id + ":stale_state");
      continue;
    }
    if (!vehicle.position_valid) {
      saw_no_position = true;
      blockers.push_back(vehicle.vehicle_id + ":no_position");
      continue;
    }
    eligible.push_back(&vehicle);
  }

  if (eligible.empty()) {
    decision.strategy = "rejected";
    if (saw_never_seen) {
      // 从未收到状态 -> 状态不确定：暂停自动分配，等状态恢复，而不是乱派
      decision.outcome = AssignmentOutcome::kIndeterminate;
      decision.strategy = "indeterminate";
      decision.reject_reason = "vehicle state unavailable (no state report yet)";
    } else if (saw_busy) {
      // 车忙 -> 暂时不可用：任务留队等待
      decision.outcome = AssignmentOutcome::kDeferred;
      decision.strategy = "deferred";
      decision.reject_reason = "all eligible vehicles are busy";
    } else if (saw_offline) {
      // 全部车离线 -> 暂时不可用：任务留队等待链路恢复（不是永久失败）
      decision.outcome = AssignmentOutcome::kDeferred;
      decision.strategy = "deferred";
      decision.reject_reason = "all eligible vehicles are offline";
    } else if (saw_quarantined) {
      // 全部车被隔离 -> 暂时不可用：等操作员恢复
      decision.outcome = AssignmentOutcome::kDeferred;
      decision.strategy = "deferred";
      decision.reject_reason = "all eligible vehicles are quarantined";
    } else if (saw_stale) {
      decision.outcome = AssignmentOutcome::kDeferred;
      decision.strategy = "deferred";
      decision.reject_reason = "vehicle state is stale";
    } else if (saw_no_position) {
      decision.outcome = AssignmentOutcome::kDeferred;
      decision.strategy = "deferred";
      decision.reject_reason = "no vehicle has a valid position";
    } else if (!saw_capable) {
      decision.outcome = AssignmentOutcome::kRejected;
      decision.reject_reason = "no vehicle with capability '" + capability + "'";
    } else {
      decision.outcome = AssignmentOutcome::kRejected;
      decision.reject_reason = "no eligible vehicle with capability '" + capability + "'";
    }
    if (!blockers.empty()) {
      decision.reject_reason += ": " + JoinReasons(blockers);
    }
    return decision;
  }

  // ---- 合格候选：按路径成本升序（距离不可算者排在后面）----
  const VehicleRuntimeState* best = nullptr;
  double best_cost = std::numeric_limits<double>::max();
  for (const auto* vehicle : eligible) {
    const auto it = request.distance_to_pickup_m.find(vehicle->vehicle_id);
    if (it == request.distance_to_pickup_m.end()) {
      continue;
    }
    if (best == nullptr || it->second < best_cost) {
      best = vehicle;
      best_cost = it->second;
    }
  }
  if (best == nullptr) {
    // 全部合格车距离都不可算 -> 不盲派（宁可不动也不把任务派给到不了取货点的车）
    decision.outcome = AssignmentOutcome::kRejected;
    decision.strategy = "rejected";
    decision.reject_reason = "no reachable pickup cost for any eligible vehicle";
    return decision;
  }

  decision.outcome = AssignmentOutcome::kAssigned;
  decision.strategy = "nearest";
  decision.vehicle_id = best->vehicle_id;
  return decision;
}

}  // namespace amr_dispatcher_core::fleet

#include "amr_dispatcher_core/dispatcher/mission_queue.hpp"

#include <algorithm>
#include <utility>

namespace amr_dispatcher_core::dispatcher {
namespace {

std::unique_ptr<MissionComparator> DefaultComparator(const std::string& name) {
  auto comparator = CreateMissionComparator(name);
  if (comparator == nullptr) {
    comparator = std::make_unique<PriorityFifoComparator>();
  }
  return comparator;
}

}  // namespace

MissionQueue::MissionQueue(Config config)
    : config_(config), comparator_(DefaultComparator(config.comparator)) {
  config_.max_size = std::max<std::size_t>(1, config_.max_size);
}

void MissionQueue::SetComparator(std::unique_ptr<MissionComparator> comparator) {
  if (comparator == nullptr) {
    return;
  }
  comparator_ = std::move(comparator);
  dirty_ = true;
}

void MissionQueue::Sort() const {
  if (!dirty_) {
    return;
  }
  auto& items = const_cast<std::vector<Mission>&>(items_);
  const MissionComparator& cmp = *comparator_;
  std::stable_sort(items.begin(), items.end(),
                   [&cmp](const Mission& a, const Mission& b) { return cmp.Before(a, b); });
  dirty_ = false;
}

MissionQueue::PushResult MissionQueue::Push(Mission mission) {
  PushResult result;
  if (mission.id.empty()) {
    result.message = "mission id must not be empty";
    return result;
  }
  if (Contains(mission.id)) {
    result.message = "duplicate mission id: " + mission.id;
    return result;
  }
  if (items_.size() >= config_.max_size) {
    result.message = "mission queue is full (" + std::to_string(config_.max_size) + ")";
    return result;
  }
  mission.state = MissionState::kPending;
  mission.result = MissionResult::kNone;
  items_.push_back(std::move(mission));
  dirty_ = true;
  result.accepted = true;
  result.message = "queued " + items_.back().id;
  return result;
}

MissionQueue::PopResult MissionQueue::PopNext() {
  PopResult result;
  Sort();
  if (items_.empty()) {
    result.queue_empty = true;
    result.message = "mission queue is empty";
    return result;
  }
  const auto it = std::find_if(items_.begin(), items_.end(), [this](const Mission& m) {
    return !IsOrderPaused(m.order_id);
  });
  if (it == items_.end()) {
    result.all_paused = true;
    result.message = "all queued missions are paused";
    return result;
  }
  result.mission = *it;
  result.mission->state = MissionState::kActive;
  result.success = true;
  result.message = "dispatched " + it->id;
  items_.erase(it);
  return result;
}

const Mission* MissionQueue::Peek() const {
  Sort();
  const auto it = std::find_if(items_.begin(), items_.end(), [this](const Mission& m) {
    return !IsOrderPaused(m.order_id);
  });
  return it == items_.end() ? nullptr : &*it;
}

std::vector<Mission> MissionQueue::PeekN(const std::size_t max_count) const {
  Sort();
  std::vector<Mission> result;
  if (max_count == 0) {
    return result;
  }
  for (const auto& item : items_) {
    if (IsOrderPaused(item.order_id)) {
      continue;  // 暂停订单不参与出队
    }
    result.push_back(item);
    if (result.size() >= max_count) {
      break;
    }
  }
  return result;
}

MissionQueue::PopResult MissionQueue::PopById(const std::string& mission_id) {
  PopResult result;
  Sort();
  const auto it = std::find_if(items_.begin(), items_.end(),
                               [&mission_id](const Mission& m) { return m.id == mission_id; });
  if (it == items_.end()) {
    result.message = "mission not found: " + mission_id;
    return result;
  }
  if (IsOrderPaused(it->order_id)) {
    result.all_paused = true;
    result.message = "order is paused: " + it->order_id;
    return result;
  }
  result.mission = *it;
  result.mission->state = MissionState::kActive;
  result.success = true;
  result.message = "dispatched " + it->id;
  items_.erase(it);
  return result;
}

bool MissionQueue::Cancel(const std::string& mission_id) {
  const auto it = std::find_if(items_.begin(), items_.end(),
                               [&mission_id](const Mission& m) { return m.id == mission_id; });
  if (it == items_.end()) {
    return false;
  }
  const std::string order_id = it->order_id;
  items_.erase(it);
  if (!order_id.empty() && IsOrderPaused(order_id)) {
    // 该订单已无排队任务时清掉暂停标记，避免残留。
    const bool still_queued =
        std::any_of(items_.begin(), items_.end(),
                    [&order_id](const Mission& m) { return m.order_id == order_id; });
    if (!still_queued) {
      paused_order_ids_.erase(order_id);
    }
  }
  return true;
}

bool MissionQueue::Reprioritize(const std::string& mission_id, const int priority) {
  const auto it = std::find_if(items_.begin(), items_.end(),
                               [&mission_id](const Mission& m) { return m.id == mission_id; });
  if (it == items_.end()) {
    return false;
  }
  it->priority = priority;
  dirty_ = true;
  return true;
}

void MissionQueue::PauseOrder(const std::string& order_id) {
  if (!order_id.empty()) {
    paused_order_ids_.insert(order_id);
  }
}

void MissionQueue::ResumeOrder(const std::string& order_id) { paused_order_ids_.erase(order_id); }

bool MissionQueue::IsOrderPaused(const std::string& order_id) const {
  return !order_id.empty() && paused_order_ids_.count(order_id) > 0;
}

std::size_t MissionQueue::CancelOrder(const std::string& order_id) {
  if (order_id.empty()) {
    return 0;
  }
  const auto before = items_.size();
  items_.erase(
      std::remove_if(items_.begin(), items_.end(),
                     [&order_id](const Mission& m) { return m.order_id == order_id; }),
      items_.end());
  paused_order_ids_.erase(order_id);
  return before - items_.size();
}

bool MissionQueue::Contains(const std::string& mission_id) const {
  return std::any_of(items_.begin(), items_.end(),
                     [&mission_id](const Mission& m) { return m.id == mission_id; });
}

std::vector<Mission> MissionQueue::Snapshot() const {
  Sort();
  std::vector<Mission> snapshot;
  snapshot.reserve(items_.size());
  for (const auto& item : items_) {
    Mission copy = item;
    copy.state = IsOrderPaused(item.order_id) ? MissionState::kPaused : MissionState::kPending;
    snapshot.push_back(std::move(copy));
  }
  return snapshot;
}

}  // namespace amr_dispatcher_core::dispatcher

