  if (!vehicle_id.empty()) {
    const auto it = vehicle_plan_pubs_.find(vehicle_id);
    if (it != vehicle_plan_pubs_.end() && it->second) {
      return it->second;
    }
  }
  return plan_pub_;  // legacy /plan（单车兼容红线）
}

