  const auto t0 = std::chrono::steady_clock::now();
  if (!backend_ctrl_->current()->WriteCommand(cmd, &err)) {
    backend_ctrl_->RecordLoss();
    RCLCPP_WARN_THROTTLE(get_logger(), *get_clock(), 1000, "WriteCommand failed: %s", err.c_str());
  } else {
