# 用 Zhang-Suen 复刻骨架提取（简化版）看结构
d=open('test/maps/demo_warehouse/map.pgm','rb').read()
i=d.index(b'255\n')+4
px=d[i:]
W,H=260,140
g=[[1 if px[r*W+c]==254 else 0 for c in range(W)] for r in range(H)]
def neighbours(g,x,y):
    return [g[y-1][x],g[y-1][x+1],g[y][x+1],g[y+1][x+1],g[y+1][x],g[y+1][x-1],g[y][x-1],g[y-1][x-1]]
def transitions(g,x,y):
    n=neighbours(g,x,y)
    return sum(1 for i in range(8) if n[i]==0 and n[(i+1)%8]==1)
changed=True
it=0
while changed and it<50:
    changed=False; it+=1
    for step in (0,1):
        rem=[]
        for y in range(1,H-1):
            for x in range(1,W-1):
                if g[y][x]==0: continue
                P2,P3,P4,P5,P6,P7,P8,P9=neighbours(g,x,y)
                s=sum([P2,P3,P4,P5,P6,P7,P8,P9])
                if s<2 or s>6: continue
                t=transitions(g,x,y)
                if t!=1: continue
                if step==0:
                    if P2*P4*P6 or P4*P6*P8: continue
                else:
                    if P2*P4*P8 or P2*P6*P8: continue
                rem.append((y,x))
        if rem:
            changed=True
            for y,x in rem: g[y][x]=0
# 打印骨架
for r in range(H):
    row=''.join('#' if g[r][c] else ' ' for c in range(W))
    if '#' in row:
        print(f"{r:3d} {row}")
