#include <cstdio>
#include <fstream>
#include <string>
#include <vector>
#include <algorithm>

#include "amr_dispatcher_core/planning/safety_space_filter.hpp"
#include "amr_dispatcher_core/planning/skeleton_extractor.hpp"
#include "amr_dispatcher_core/planning/topology_graph_builder.hpp"

using namespace amr_dispatcher_core::planning;

// 读 PGM (P5) -> MapGrid（模拟 nav2_map_server 的翻转语义）
static bool LoadPgm(const std::string& path, MapGrid* grid) {
  std::ifstream in(path, std::ios::binary);
  if (!in) return false;
  std::string magic;
  in >> magic;
  if (magic != "P5") return false;
  int w = 0, h = 0, maxv = 0;
  in >> w >> h >> maxv;
  in.get();
  std::vector<uint8_t> px(static_cast<size_t>(w) * h);
  in.read(reinterpret_cast<char*>(px.data()), static_cast<std::streamsize>(px.size()));
  // PGM 顶行 = 图顶；OccupancyGrid 的 data 行 0 = 世界 y 最小（底部）
  grid->width = static_cast<uint32_t>(w);
  grid->height = static_cast<uint32_t>(h);
  grid->resolution = 0.05;
  grid->origin_x = 0.0; grid->origin_y = 0.0; grid->origin_yaw = 0.0;
  grid->data.assign(static_cast<size_t>(w) * h, 0);
  for (int r = 0; r < h; ++r) {
    const int orow = h - 1 - r;
    for (int c = 0; c < w; ++c) {
      const uint8_t v = px[static_cast<size_t>(r) * w + c];
      // nav2: 白色(254) -> 0 占用? 实际 nav2 把 pgm 灰度按阈值转成 occupancy
      // 254 (白) = 自由 -> occupancy 0；0 (黑) = 障碍 -> occupancy 100
      grid->data[static_cast<size_t>(orow) * w + c] = (v >= 200) ? 0 : 100;
    }
  }
  return true;
}

int main(int argc, char** argv) {
  MapGrid grid;
  if (!LoadPgm(argv[1], &grid)) { printf("load fail\n"); return 1; }
  SafetyFilterConfig sc;
  sc.robot_radius_m = 0.25; sc.safety_margin_m = 0.05;
  PruneConfig pc; pc.min_branch_length_m = 0.5; pc.resolution = 0.05;
  TopologyBuilderConfig bc; bc.max_snap_dist_m = 2.0; bc.map_hash = "dbg"; bc.graph_version = "v1";

  BinaryGrid safe = FilterSafetySpace(grid, sc);
  BinaryGrid skel = ZhangSuenThinning(safe);
  printf("skeleton pixels: ");
  int n = 0; for (auto v : skel.data) n += v;
  printf("%d\n", n);
  // 打印骨架
  for (uint32_t r = 0; r < skel.height; ++r) {
    std::string line;
