    for (auto& n2 : res.catalog.road_nodes) printf("roadnode %s (%.3f, %.3f)\n", n2.id.c_str(), n2.x, n2.y);
    for (auto& e : res.catalog.edges) printf("edge %s -> %s len=%.3f npts=%zu\n", e.from.c_str(), e.to.c_str(), e.distance_m, e.polyline.size());
