#pragma once
// 从 ROS /map 抓取的 JSON dump 重建 MapGrid（OccupancyGrid 语义：row 0 = 最小 y）
#include <cstdint>
#include <cstdio>
#include <cstdlib>
#include <string>
#include <vector>
#include "amr_dispatcher_core/planning/map_geometry_utils.hpp"
using namespace amr_dispatcher_core::planning;
static bool LoadOccDump(const char* path, MapGrid* grid) {
  FILE* f = fopen(path, "r");
  if (!f) return false;
  // 简单解析：找 "w": N, "h": N, "res": R, "ox":, "oy":, "data":[...]
  char buf[1 << 20];
  size_t n = fread(buf, 1, sizeof(buf) - 1, f);
  buf[n] = 0;
  fclose(f);
  auto num = [&](const char* key) -> double {
    const char* p = strstr(buf, key);
    if (!p) return 0;
    p = strchr(p, ':');
    return p ? atof(p + 1) : 0;
  };
  grid->width = (uint32_t)num("\"w\"");
  grid->height = (uint32_t)num("\"h\"");
  grid->resolution = num("\"res\"");
  grid->origin_x = num("\"ox\"");
  grid->origin_y = num("\"oy\"");
  grid->origin_yaw = 0.0;
  const char* dp = strstr(buf, "\"data\":[");
  dp += 8;
  grid->data.clear();
  grid->data.reserve((size_t)grid->width * grid->height);
  while (*dp && *dp != ']') {
    while (*dp == ',' || *dp == ' ') dp++;
    if (*dp == ']') break;
    char* endp = nullptr;
    long v = strtol(dp, &endp, 10);
    if (endp == dp) break;
    grid->data.push_back((int8_t)v);
    dp = endp;
  }
  return grid->data.size() == (size_t)grid->width * grid->height;
}
