    RCLCPP_WARN_THROTTLE(get_logger(), *get_clock(), 5000,
                         "VDA 5050 state identity mismatch: topic vehicle %s but "
                         "serialNumber %s — dropped",
                         vehicle_id.c_str(), report->vehicle_id.c_str());
    return;
