  EXPECT_TRUE(HasResource(plan.windows, "route_node:B"));
  EXPECT_TRUE(HasResource(plan.windows, "route_node:C"));
  EXPECT_DOUBLE_EQ(plan.total_delay_sec, 0.0);
}

