  for (const auto& robot : catalog.robots) {
    if (!RobotAvailableForTask(robot) || !RobotHasCapability(robot, required_capability)) {
      continue;
    }
    if (RobotUnavailable(robot, unavailable_robot_ids)) {
      continue;
