namespace amr_dispatcher_ros {

// 派发三态决策（评审 A7）：把选车结果映射为调度层的**处置动作**。
enum class DispatchAction {
  kDispatch,             // 选到车 -> 继续派发
  kStayQueued,           // 暂时不可用 -> 任务留队，下 tick 重试
  kPauseAutoAssignment,  // 状态不确定 -> 暂停自动分配，等状态恢复
  kFailMission,          // 永久不满足 -> 该单判负
};

struct DispatchDecision {
  DispatchAction action = DispatchAction::kStayQueued;
  std::string reason;
};

inline DispatchDecision DecideDispatchAction(
    amr_dispatcher_core::fleet::AssignmentOutcome outcome,
    const std::string& reason = "") {
  using amr_dispatcher_core::fleet::AssignmentOutcome;
  switch (outcome) {
    case AssignmentOutcome::kAssigned:
      return {DispatchAction::kDispatch, reason};
    case AssignmentOutcome::kDeferred:
      return {DispatchAction::kStayQueued, reason};
    case AssignmentOutcome::kIndeterminate:
      return {DispatchAction::kPauseAutoAssignment, reason};
    case AssignmentOutcome::kRejected:
      return {DispatchAction::kFailMission, reason};
  }
  return {DispatchAction::kFailMission, reason};
}
