TEST(ResourceTableTest, ExtendTimeSpaceReservation_ExtendsOwnWindow) {
  ResourceTable t;
  const auto t0 = std::chrono::steady_clock::now();
  std::string msg;
  ASSERT_TRUE(t.ReserveTimeSpace("m1", "route_edge:A__B", t0, t0 + 10s, &msg));

