  const auto path = WriteFile("facilities.yaml", R"(resources:
  - id: charger_main
    station_id: dock
)");

  // type 缺失 -> 记录不完整 -> 整份目录判负
  EXPECT_FALSE(LoadFacilityCatalog(path).has_value());
