cat > /tmp/console_check.mjs <<'EOF'
// 用 CDP 驱动 headless Chrome 走一遍 Web 控制台的受管车辆面板与强清/恢复交互。
// 目的：把"浏览器端手工验证"从人工变成可复现的自动化验收。
import { WebSocket } from 'ws';

const BASE = process.env.CONSOLE_BASE || 'http://127.0.0.1:18090';

async function cdpTarget() {
  const res = await fetch('http://127.0.0.1:9222/json/new?' + encodeURIComponent(BASE + '/'), { method: 'PUT' });
  return res.json();
}

const target = await cdpTarget();
const ws = new WebSocket(target.webSocketDebuggerUrl);
let id = 0;
const pending = new Map();
const logs = [];
ws.on('message', (raw) => {
  const msg = JSON.parse(raw.toString());
  if (msg.id && pending.has(msg.id)) { pending.get(msg.id)(msg); pending.delete(msg.id); }
  if (msg.method === 'Runtime.consoleAPICalled') {
    logs.push(msg.params.type + ': ' + msg.params.args.map(a => a.value ?? a.description ?? JSON.stringify(a.preview ?? '')).join(' '));
  }
  if (msg.method === 'Runtime.exceptionThrown') {
    logs.push('EXCEPTION: ' + (msg.params.exceptionDetails.exception?.description || msg.params.exceptionDetails.text));
  }
});
await new Promise(r => ws.on('open', r));
function send(method, params = {}) {
  const mid = ++id;
  ws.send(JSON.stringify({ id: mid, method, params }));
  return new Promise(res => pending.set(mid, res));
}
async function evalJs(expr) {
  const r = await send('Runtime.evaluate', { expression: expr, awaitPromise: true, returnByValue: true });
  if (r.result?.exceptionDetails) throw new Error(r.result.exceptionDetails.exception?.description || 'eval error');
  return r.result?.result?.value;
}

await send('Runtime.enable');
await send('Page.enable');
await send('Page.navigate', { url: BASE + '/' });
await new Promise(r => setTimeout(r, 3000));

const out = {};
out.title = await evalJs('document.title');
out.hasVehiclePanel = await evalJs(`!!document.getElementById('vehicleLinksTable')`);
out.hasPositionCheckbox = await evalJs(`!!document.getElementById('positionVerified')`);
out.baseUrlValue = await evalJs(`document.getElementById('baseUrl') ? document.getElementById('baseUrl').value : null`);
// 面板内容
await evalJs(`document.getElementById('refreshBtn').click()`);
await new Promise(r => setTimeout(r, 1500));
out.panelText = await evalJs(`document.getElementById('vehicleLinksTable').innerText`);
out.panelHasTable = await evalJs(`!!document.querySelector('#vehicleLinksTable table')`);
out.consoleLogs = logs;
console.log(JSON.stringify(out, null, 2));
ws.close();
process.exit(0);
EOF
