// 目的：把"浏览器端手工验证"从人工变成可复现的自动化验收。
const BASE = process.env.CONSOLE_BASE || 'http://172.18.0.2:18090';

const res = await fetch('http://127.0.0.1:9222/json/new?' + encodeURIComponent(BASE + '/'), { method: 'PUT' });
const target = await res.json();
const ws = new WebSocket(target.webSocketDebuggerUrl);
let id = 0;
const pending = new Map();
const logs = [];
ws.addEventListener('message', (ev) => {
  const msg = JSON.parse(ev.data);
  if (msg.id && pending.has(msg.id)) { pending.get(msg.id)(msg); pending.delete(msg.id); }
  if (msg.method === 'Runtime.consoleAPICalled') {
    logs.push(msg.params.type + ': ' + msg.params.args.map(a => a.value ?? a.description ?? '').join(' '));
  }
  if (msg.method === 'Runtime.exceptionThrown') {
    logs.push('EXCEPTION: ' + (msg.params.exceptionDetails.exception?.description || msg.params.exceptionDetails.text));
  }
});
await new Promise(r => ws.addEventListener('open', r));
function send(method, params = {}) {
  const mid = ++id;
  ws.send(JSON.stringify({ id: mid, method, params }));
  return new Promise(res => pending.set(mid, res));
}
async function evalJs(expr) {
  const r = await send('Runtime.evaluate', { expression: expr, awaitPromise: true, returnByValue: true });
  if (r.result?.exceptionDetails) throw new Error(r.result.exceptionDetails.exception?.description || 'eval error');
  return r.result?.result?.value;
}
const sleep = ms => new Promise(r => setTimeout(r, ms));

await send('Runtime.enable');
await send('Page.enable');
await send('Page.navigate', { url: BASE + '/' });
await sleep(3000);

const out = {};
out.title = await evalJs('document.title');
out.hasVehiclePanel = await evalJs(`!!document.getElementById('vehicleLinksTable')`);
out.hasPositionCheckbox = await evalJs(`!!document.getElementById('positionVerified')`);

// 面板用输入框里的 baseUrl：先改成实际网关地址再刷新
await evalJs(`document.getElementById('baseUrl').value = ${JSON.stringify(BASE)}`);
await evalJs(`document.getElementById('refreshBtn').click()`);
await sleep(1500);
out.panelText = await evalJs(`document.getElementById('vehicleLinksTable').innerText`);
out.panelHasTable = await evalJs(`!!document.querySelector('#vehicleLinksTable table')`);
out.panelRowCount = await evalJs(`document.querySelectorAll('#vehicleLinksTable table tr').length - 1`);
out.panelHeaderCells = await evalJs(
  `Array.from(document.querySelectorAll('#vehicleLinksTable table tr:first-child th')).map(t => t.innerText.trim())`);

// ---- 强清交互：未填审计字段 -> 前端必须拦下 ----
await evalJs(`document.getElementById('forceClearVehicleId').value = 'ui_amr_01'`);
await evalJs(`document.getElementById('forceClearBtn').click()`);
await sleep(500);
out.statusAfterMissingAudit = await evalJs(`document.getElementById('status') ? document.getElementById('status').innerText : ''`);

// 填齐审计字段 + 拦截 window.confirm（记录被弹窗内容）
await evalJs(`document.getElementById('forceClearOperator').value = 'operator_ui'`);
await evalJs(`document.getElementById('forceClearReason').value = 'UI 自动化验收：车辆报废下线'`);
await evalJs(`window.__confirmText = null; window.confirm = (msg) => { window.__confirmText = msg; return true; };`);
await evalJs(`document.getElementById('forceClearBtn').click()`);
await sleep(2000);
out.confirmPrompt = await evalJs(`window.__confirmText`);
out.statusAfterForceClear = await evalJs(`document.getElementById('status') ? document.getElementById('status').innerText : ''`);
out.panelAfterForceClear = await evalJs(`document.getElementById('vehicleLinksTable').innerText`);

// ---- 恢复交互：未勾选"已核实物理位置" -> 必须被拦下 ----
await evalJs(`document.getElementById('positionVerified').checked = false`);
await evalJs(`document.getElementById('restoreLinkBtn').click()`);
await sleep(500);
out.statusAfterRestoreWithoutVerify = await evalJs(`document.getElementById('status') ? document.getElementById('status').innerText : ''`);

out.consoleLogs = logs;
console.log(JSON.stringify(out, null, 2));
ws.close();
process.exit(0);
EOF
