  const started = Date.now();
  while (Date.now() - started < deadlineMs) {
    try {
      return await fetchJson(`http://127.0.0.1:${CDP_PORT}/json/version`);
    } catch {
      await new Promise((r) => setTimeout(r, 300));
    }
  }
  throw new Error('CDP 端口未就绪: ' + CDP_PORT);
