  `http://127.0.0.1:${CDP_PORT}/json/new?${encodeURIComponent(BASE + '/')}`,
  { method: 'PUT' }
);

const ws = new WebSocket(target.webSocketDebuggerUrl);
let msgId = 0;
const pending = new Map();
const consoleErrors = [];

