    await fillAudit('wc_amr_01', 'operator_ui', 'UI 验收：在线车强清应被拒');
    await evalJs(`document.getElementById('forceClearBtn').click(); true;`);
    await sleep(2000);
    const messages = (await alerts()).join(' | ');
    check(
      '在线车强清被服务端拒绝',
