      {"second", [](const ChassisBackendConfig&) { return std::make_unique<StubBackend>("second"); }},
  };
  BackendDegradationController ctrl(
      std::move(descs), {},
      {.warmup_samples = 4, .demote_loss_rate = 0.3, .cooldown = 0ms});
