  *first_open_ok = false;
  for (int i = 0; i < 50; ++i) ctrl.RecordSuccess(1.0);
  // 回切失败 -> 留在 second，连接不得断成空档
  EXPECT_FALSE(ctrl.EvaluateAndMaybeSwitch(nullptr));
