403	          amr_dispatcher_core::planning::MapGrid grid;
404	          grid.width = static_cast<uint32_t>(width);
405	          grid.height = static_cast<uint32_t>(height);
406	          grid.resolution = res;
407	          grid.origin_x = origin_x;
408	          grid.origin_y = origin_y;
409	          grid.origin_yaw = 0.0;
410	          grid.data.assign(width * height, 0); // 默认为空闲通行区
411	
412	          // 提取 grid_data 数组 (如 [0, 100, -1, ...])
413	          auto grid_pos = body.find("\"grid_data\"");
414	          if (grid_pos != std::string::npos) {
415	            auto arr_start = body.find('[', grid_pos);
416	            auto arr_end = body.find(']', arr_start);
417	            if (arr_start != std::string::npos && arr_end != std::string::npos) {
418	              std::string arr_str = body.substr(arr_start + 1, arr_end - arr_start - 1);
419	              std::stringstream ss(arr_str);
420	              std::string item;
421	              size_t idx = 0;
422	              while (std::getline(ss, item, ',') && idx < grid.data.size()) {
423	                try {
424	                  grid.data[idx++] = static_cast<int8_t>(std::stoi(item));
425	                } catch (...) {}
426	              }
427	            }
428	          }
429	
430	          // 提取 anchors: [{"id":"A","type":"pickup","x":1.0,"y":2.0}, ...]
431	          std::vector<amr_dispatcher_core::planning::AnchorStation> anchors;
432	          auto anchors_pos = body.find("\"anchors\"");
433	          if (anchors_pos != std::string::npos) {
434	            auto arr_start = body.find('[', anchors_pos);
435	            auto arr_end = body.find(']', arr_start);
436	            if (arr_start != std::string::npos && arr_end != std::string::npos) {
437	              std::string arr_str = body.substr(arr_start + 1, arr_end - arr_start - 1);
438	              size_t obj_start = 0;
439	              while ((obj_start = arr_str.find('{', obj_start)) != std::string::npos) {
440	                size_t obj_end = arr_str.find('}', obj_start);
441	                if (obj_end == std::string::npos) break;
442	                std::string obj_str = arr_str.substr(obj_start, obj_end - obj_start + 1);
443	
444	                auto extract_str = [&obj_str](const std::string& k) -> std::string {
445	                  auto p = obj_str.find("\"" + k + "\"");
446	                  if (p == std::string::npos) return "";
447	                  p = obj_str.find(':', p);
448	                  if (p == std::string::npos) return "";
449	                  auto q1 = obj_str.find('\"', p);
450	                  if (q1 == std::string::npos) return "";
451	                  auto q2 = obj_str.find('\"', q1 + 1);
452	                  if (q2 == std::string::npos) return "";
453	                  return obj_str.substr(q1 + 1, q2 - q1 - 1);
454	                };
455	                auto extract_num = [&obj_str](const std::string& k) -> double {
456	                  auto p = obj_str.find("\"" + k + "\"");
457	                  if (p == std::string::npos) return 0.0;
458	                  p = obj_str.find(':', p);
459	                  if (p == std::string::npos) return 0.0;
460	                  return std::stod(obj_str.substr(p + 1));
461	                };
462	
463	                amr_dispatcher_core::planning::AnchorStation a;
464	                a.id = extract_str("id");
465	                a.type = extract_str("type");
466	                if (a.type.empty()) a.type = "normal";
467	                a.x = extract_num("x");
468	                a.y = extract_num("y");
469	                a.yaw = extract_num("yaw");
470	                if (!a.id.empty()) {
471	                  anchors.push_back(a);
472	                }
473	                obj_start = obj_end + 1;
474	              }
475	            }
476	          }
477	
478	          // 核心库自动化流水线：腐蚀 -> 细化 -> 剪枝 -> 拓扑构建
479	          amr_dispatcher_core::planning::SafetyFilterConfig sf_cfg;
480	          sf_cfg.robot_radius_m = 0.25;
481	          sf_cfg.safety_margin_m = 0.05;
482	          auto safe_grid = amr_dispatcher_core::planning::FilterSafetySpace(grid, sf_cfg);
483	          auto skel = amr_dispatcher_core::planning::ZhangSuenThinning(safe_grid);
484	
485	          std::vector<amr_dispatcher_core::planning::PixelCoord> protected_points;
486	          for (const auto& a : anchors) {
487	            amr_dispatcher_core::planning::WorldCoord w{a.x, a.y};
488	            protected_points.push_back(amr_dispatcher_core::planning::WorldToPixel(w, grid));
489	          }
490	          amr_dispatcher_core::planning::PruneConfig pr_cfg;
491	          pr_cfg.min_branch_length_m = 0.5;
492	          pr_cfg.resolution = res;
493	          auto pruned = amr_dispatcher_core::planning::PruneSkeletonProtected(skel, protected_points, pr_cfg);
494	
495	          amr_dispatcher_core::planning::TopologyBuilderConfig tb_cfg;
496	          tb_cfg.max_snap_dist_m = 3.0;
497	          tb_cfg.map_hash = "web_upload_" + std::to_string(width) + "x" + std::to_string(height);
498	          tb_cfg.graph_version = "v1_web";
499	          auto build_res = amr_dispatcher_core::planning::BuildTopologyCatalog(pruned, grid, anchors, tb_cfg);
500	
501	          if (!build_res.success) {
502	            status_code = "422 Unprocessable Entity";
503	            response_body = "{\"status\":\"error\",\"message\":\"" + build_res.error_message + "\"}";
504	          } else {
505	            // 写入 config/generated/stations.yaml (tmp + rename 原子替换)
506	            std::filesystem::path final_path("config/generated/stations.yaml");
507	            std::filesystem::create_directories(final_path.parent_path());
508	            std::filesystem::path tmp_path("config/generated/stations.yaml.tmp");
509	
510	            std::ofstream out(tmp_path);
511	            out << "version:\n";
512	            out << "  map_hash: \"" << build_res.catalog.map_hash << "\"\n";
513	            out << "  graph_version: \"" << build_res.catalog.graph_version << "\"\n";
514	            out << "stations:\n";
515	            for (const auto& s : build_res.catalog.stations) {
516	              out << "  - id: \"" << s.id << "\"\n";
517	              out << "    x: " << s.x << "\n";
518	              out << "    y: " << s.y << "\n";
519	              out << "    yaw: " << s.yaw << "\n";
520	              out << "    type: \"" << s.type << "\"\n";
521	            }
522	            out << "road_nodes:\n";
523	            for (const auto& rn : build_res.catalog.road_nodes) {
524	              out << "  - id: \"" << rn.id << "\"\n";
525	              out << "    x: " << rn.x << "\n";
526	              out << "    y: " << rn.y << "\n";
527	              out << "    yaw: " << rn.yaw << "\n";
528	            }
529	            out << "edges:\n";
530	            for (const auto& e : build_res.catalog.edges) {
531	              out << "  - from: \"" << e.from << "\"\n";
532	              out << "    to: \"" << e.to << "\"\n";
533	              out << "    distance_m: " << e.distance_m << "\n";
534	              out << "    bidirectional: " << (e.bidirectional ? "true" : "false") << "\n";
535	              out << "    enabled: true\n";
536	              out << "    polyline:\n";
537	              for (const auto& pt : e.polyline) {
538	                out << "      - [" << pt.first << ", " << pt.second << "]\n";
539	              }
540	            }
541	            out.close();
542	            std::filesystem::rename(tmp_path, final_path);
543	
544	            response_body = "{\"status\":\"ok\",\"stations_count\":" + std::to_string(build_res.catalog.stations.size()) +
545	                            ",\"road_nodes_count\":" + std::to_string(build_res.catalog.road_nodes.size()) +
546	                            ",\"edges_count\":" + std::to_string(build_res.catalog.edges.size()) +
547	                            ",\"map_hash\":\"" + build_res.catalog.map_hash + "\"}";
548	          }
549	        }
550	      } catch (const std::exception& e) {
551	        status_code = "500 Internal Server Error";
552	        response_body = "{\"error\":\"" + std::string(e.what()) + "\"}";
553	      }
554	    } else {
555	      status_code = "404 Not Found";
556	      response_body = "{\"error\":\"not_found\"}";
557	    }
558	
559	    std::ostringstream resp;
560	    resp << "HTTP/1.1 " << status_code << "\r\n";
561	    resp << "Content-Type: " << content_type << "\r\n";
562	    resp << "Content-Length: " << response_body.size() << "\r\n";
563	    resp << "Access-Control-Allow-Origin: *\r\n";
564	    resp << "Access-Control-Allow-Methods: GET, POST, OPTIONS\r\n";
565	    resp << "Connection: close\r\n\r\n";
566	    resp << response_body;
567	
568	    std::string resp_str = resp.str();
569	    write(client_fd, resp_str.c_str(), resp_str.size());
570	  }
