608	  std::string GetQueryParam(const std::string& query, const std::string& key, const std::string& fallback = "") {
609	    std::string target = key + "=";
610	    auto pos = query.find(target);
611	    if (pos == std::string::npos) return fallback;
612	    auto end = query.find('&', pos);
613	    if (end == std::string::npos) {
614	      return query.substr(pos + target.size());
615	    }
616	    return query.substr(pos + target.size(), end - (pos + target.size()));
617	  }
