619	  // 极简 JSON 字符串字段提取（请求体由本项目自己的控制台产生，格式可控）：
620	  // 形如 "key": "value" -> value；缺失或非字符串返回空串。
621	  std::string JsonStringField(const std::string& body, const std::string& key) {
622	    const std::string target = "\"" + key + "\"";
623	    auto pos = body.find(target);
624	    if (pos == std::string::npos) return "";
625	    pos = body.find(':', pos);
626	    if (pos == std::string::npos) return "";
627	    ++pos;
628	    while (pos < body.size() && std::isspace(static_cast<unsigned char>(body[pos]))) ++pos;
629	    if (pos >= body.size() || body[pos] != '"') return "";
630	    ++pos;
631	    std::string value;
632	    while (pos < body.size() && body[pos] != '"') {
633	      if (body[pos] == '\\' && pos + 1 < body.size()) ++pos;  // 跳过转义字符
634	      value.push_back(body[pos]);
635	      ++pos;
636	    }
637	    return value;
638	  }
