640	  // 极简 JSON 布尔字段提取：true / false。
641	  bool JsonBoolField(const std::string& body, const std::string& key) {
642	    const std::string target = "\"" + key + "\"";
643	    auto pos = body.find(target);
644	    if (pos == std::string::npos) return false;
645	    pos = body.find(':', pos);
646	    if (pos == std::string::npos) return false;
647	    ++pos;
648	    while (pos < body.size() && std::isspace(static_cast<unsigned char>(body[pos]))) ++pos;
649	    return body.compare(pos, 4, "true") == 0;
650	  }
