      return IntParseStatus::kOutOfRange;
    }
  }
  if (negative) {
    acc = -acc;
  }
  if (acc < -2147483648LL || acc > 2147483647LL) {
    return IntParseStatus::kOutOfRange;
  }
  if (out != nullptr) {
    *out = static_cast<std::int32_t>(acc);
  }
  return IntParseStatus::kOk;
}

