159	// 错误响应后先把对端还在发送的数据读掉再关闭。
160	// 直接 close 一个仍有未读数据的连接会发 RST，客户端可能连 400/413 都收不到。
161	// 上限 2 MiB + 单次读超时，恶意客户端最多多占一个读超时。
162	void DrainForClose(int fd, std::size_t max_bytes = 2U * 1024U * 1024U) {
163	  char sink[4096];
164	  std::size_t drained = 0;
165	  while (drained < max_bytes) {
166	    const ssize_t n = ::read(fd, sink, sizeof(sink));
167	    if (n > 0) {
168	      drained += static_cast<std::size_t>(n);
169	      continue;
170	    }
171	    if (n < 0 && errno == EINTR) continue;
172	    return;
173	  }
174	}
