// 与 tools 侧同名函数语义一致：控制字符一律转义，非法 JSON 字符不裸出。
std::string Escape(const std::string& input) {
  std::string out;
  out.reserve(input.size() + 8);
  for (const char raw : input) {
    const unsigned char c = static_cast<unsigned char>(raw);
    switch (c) {
      case '"': out += "\\\""; break;
      case '\\': out += "\\\\"; break;
      case '\b': out += "\\b"; break;
