#include "amr_dispatcher_core/fleet/vehicle_assignment_request_builder.hpp"

#include <algorithm>

#include "amr_dispatcher_core/fleet/fleet_catalog.hpp"

namespace amr_dispatcher_core::fleet {

std::vector<std::size_t> StableVehicleOrder(const std::vector<VehicleRuntimeState>& vehicles) {
  std::vector<std::size_t> order(vehicles.size());
  for (std::size_t i = 0; i < order.size(); ++i) {
    order[i] = i;
  }
  // 按 vehicle_id 字典序；同 id（不应出现）时用原始下标兜底，保证全序
  std::stable_sort(order.begin(), order.end(), [&vehicles](std::size_t a, std::size_t b) {
    if (vehicles[a].vehicle_id != vehicles[b].vehicle_id) {
      return vehicles[a].vehicle_id < vehicles[b].vehicle_id;
    }
    return a < b;
  });
  return order;
}

VehicleAssignmentRequest BuildVehicleAssignmentRequest(
    const VehicleAssignmentRequestInputs& inputs) {
  VehicleAssignmentRequest request;
  request.requested_vehicle_id = inputs.requested_vehicle_id;
  request.pickup_station_id = inputs.pickup_station_id;
  request.dropoff_station_id = inputs.dropoff_station_id;
  request.required_capability = inputs.required_capability;
  request.min_battery_percent = inputs.min_battery_percent;
  request.state_max_age_ms = inputs.state_max_age_ms;

  // 保序：调用方给的是无序容器导出的列表，遍历序不稳定；先按 id 排序，
  // 保证同分时裁决顺序确定（核心按输入顺序 tiebreak）。
  const auto order = StableVehicleOrder(inputs.vehicles);
  request.vehicles.reserve(order.size());
  for (const auto idx : order) {
    request.vehicles.push_back(inputs.vehicles[idx]);
  }

  // 到取货点的路网成本（评审问题 3：路网路径成本，非欧氏距离）
  const bool can_estimate = inputs.catalog != nullptr && inputs.catalog_loaded &&
                            !inputs.pickup_station_id.empty();
  if (!can_estimate) {
    return request;
  }
  for (const auto& state : request.vehicles) {
    const auto cost = EstimateVehicleApproachCost(
        *inputs.catalog, state.position_x, state.position_y, state.current_station_id,
        inputs.pickup_station_id);
    if (cost.has_value()) {
      request.distance_to_pickup_m[state.vehicle_id] = *cost;
    }
  }
  return request;
}

}  // namespace amr_dispatcher_core::fleet

#include "amr_dispatcher_core/fleet/vehicle_assignment_request_builder.hpp"

#include <gtest/gtest.h>

#include <string>
#include <vector>

using namespace amr_dispatcher_core::fleet;
using amr_dispatcher_core::catalog::CatalogStationEdge;
using amr_dispatcher_core::catalog::Station;
using amr_dispatcher_core::catalog::StationCatalog;

namespace {

StationCatalog MakeStations() {
  StationCatalog catalog;
  catalog.stations.push_back(Station{"dock", "map", 0.0, 0.0, 0.0});
  catalog.stations.push_back(Station{"receiving", "map", 1.0, 0.0, 0.0});
  catalog.stations.push_back(Station{"storage_a", "map", 2.0, 0.0, 0.0});
  catalog.edges.push_back(CatalogStationEdge{"dock", "receiving", 3.0, true, true});
  catalog.edges.push_back(CatalogStationEdge{"receiving", "storage_a", 1.0, true, true});
  return catalog;
}

VehicleRuntimeState MakeVehicle(const std::string& id, double battery = 100.0) {
  VehicleRuntimeState v;
  v.vehicle_id = id;
  v.battery_percent = battery;
  v.position_valid = true;
  return v;
}

VehicleAssignmentRequestInputs MakeInputs(std::vector<VehicleRuntimeState> vehicles) {
  VehicleAssignmentRequestInputs inputs;
  inputs.vehicles = std::move(vehicles);
  inputs.pickup_station_id = "storage_a";
  inputs.dropoff_station_id = "dock";
  inputs.required_capability = "transport";
  inputs.state_max_age_ms = 5000;
  return inputs;
}

}  // namespace

TEST(VehicleAssignmentRequestBuilderTest, CopiesTaskFields) {
  auto inputs = MakeInputs({MakeVehicle("v1")});
  inputs.requested_vehicle_id = "v1";
  inputs.min_battery_percent = 25.0;
  const auto request = BuildVehicleAssignmentRequest(inputs);
  EXPECT_EQ(request.requested_vehicle_id, "v1");
  EXPECT_EQ(request.pickup_station_id, "storage_a");
  EXPECT_EQ(request.dropoff_station_id, "dock");
  EXPECT_EQ(request.required_capability, "transport");
  EXPECT_DOUBLE_EQ(request.min_battery_percent, 25.0);
  EXPECT_EQ(request.state_max_age_ms, 5000);
}

// 核心属性：同分时的裁决顺序必须由 id 决定，而不是容器的哈希遍历序。
TEST(VehicleAssignmentRequestBuilderTest, VehiclesAreSortedByIdRegardlessOfInputOrder) {
  const auto request = BuildVehicleAssignmentRequest(
      MakeInputs({MakeVehicle("zeta"), MakeVehicle("alpha"), MakeVehicle("mid")}));
  ASSERT_EQ(request.vehicles.size(), 3u);
  EXPECT_EQ(request.vehicles[0].vehicle_id, "alpha");
  EXPECT_EQ(request.vehicles[1].vehicle_id, "mid");
  EXPECT_EQ(request.vehicles[2].vehicle_id, "zeta");
}

TEST(VehicleAssignmentRequestBuilderTest, StableOrderIsPermutationOfInput) {
  const std::vector<VehicleRuntimeState> vehicles{MakeVehicle("b"), MakeVehicle("a"),
                                                  MakeVehicle("c")};
  const auto order = StableVehicleOrder(vehicles);
  ASSERT_EQ(order.size(), 3u);
  std::vector<std::string> ids;
  for (const auto idx : order) {
    ASSERT_LT(idx, vehicles.size());
    ids.push_back(vehicles[idx].vehicle_id);
  }
  EXPECT_EQ(ids, (std::vector<std::string>{"a", "b", "c"}));
}

TEST(VehicleAssignmentRequestBuilderTest, NoCatalogMeansNoDistanceEstimates) {
  const auto request = BuildVehicleAssignmentRequest(MakeInputs({MakeVehicle("v1")}));
  EXPECT_TRUE(request.distance_to_pickup_m.empty());
}

TEST(VehicleAssignmentRequestBuilderTest, CatalogNotLoadedMeansNoDistanceEstimates) {
  const StationCatalog catalog = MakeStations();
  auto inputs = MakeInputs({MakeVehicle("v1")});
  inputs.catalog = &catalog;
  inputs.catalog_loaded = false;  // 有目录但未加载：仍不算成本
  const auto request = BuildVehicleAssignmentRequest(inputs);
  EXPECT_TRUE(request.distance_to_pickup_m.empty());
}

TEST(VehicleAssignmentRequestBuilderTest, EmptyPickupStationMeansNoDistanceEstimates) {
  const StationCatalog catalog = MakeStations();
  auto inputs = MakeInputs({MakeVehicle("v1")});
  inputs.pickup_station_id.clear();
  inputs.catalog = &catalog;
  inputs.catalog_loaded = true;
  const auto request = BuildVehicleAssignmentRequest(inputs);
  EXPECT_TRUE(request.distance_to_pickup_m.empty());
}

TEST(VehicleAssignmentRequestBuilderTest, DistanceUsesRouteNetworkCost) {
  // dock -> receiving (3.0) -> storage_a (1.0) = 4.0m 路网成本；
  // 欧氏距离只有 2.0m —— 断言用的是路网值（评审问题 3）
  const StationCatalog catalog = MakeStations();
  auto inputs = MakeInputs({MakeVehicle("v1")});
  inputs.catalog = &catalog;
  inputs.catalog_loaded = true;
  auto v = MakeVehicle("v1");
  v.current_station_id = "dock";
  inputs.vehicles = {v};
  const auto request = BuildVehicleAssignmentRequest(inputs);
  ASSERT_EQ(request.distance_to_pickup_m.count("v1"), 1u);
  EXPECT_DOUBLE_EQ(request.distance_to_pickup_m.at("v1"), 4.0);
}

TEST(VehicleAssignmentRequestBuilderTest, UnreachableVehicleHasNoDistanceEntry) {
  // 目标站点不在目录里：EstimateVehicleApproachCost 返回 nullopt ->
  // 不写距离项（核心据此把该车判为"距离不可算"，绝不盲派）
  const StationCatalog catalog = MakeStations();
  auto inputs = MakeInputs({MakeVehicle("v1")});
  inputs.pickup_station_id = "nonexistent";
  inputs.catalog = &catalog;
  inputs.catalog_loaded = true;
  auto v = MakeVehicle("v1");
  v.current_station_id = "dock";
  inputs.vehicles = {v};
  const auto request = BuildVehicleAssignmentRequest(inputs);
  EXPECT_TRUE(request.distance_to_pickup_m.empty());
}

TEST(VehicleAssignmentRequestBuilderTest, EmptyFleetProducesEmptyRequest) {
  const auto request = BuildVehicleAssignmentRequest(MakeInputs({}));
  EXPECT_TRUE(request.vehicles.empty());
  EXPECT_TRUE(request.distance_to_pickup_m.empty());
}

TEST(VehicleAssignmentRequestBuilderTest, PreservesDynamicStateFields) {
  auto v = MakeVehicle("v1", 42.0);
  v.online = false;
  v.busy = true;
  v.position_valid = true;
  v.position_x = 1.5;
  v.position_y = -2.5;
  v.current_station_id = "dock";
  v.quarantined = true;
  const auto request = BuildVehicleAssignmentRequest(MakeInputs({v}));
  ASSERT_EQ(request.vehicles.size(), 1u);
  const auto& out = request.vehicles[0];
  EXPECT_FALSE(out.online);
  EXPECT_TRUE(out.busy);
  EXPECT_TRUE(out.quarantined);
  EXPECT_DOUBLE_EQ(out.battery_percent, 42.0);
  EXPECT_DOUBLE_EQ(out.position_x, 1.5);
  EXPECT_DOUBLE_EQ(out.position_y, -2.5);
  EXPECT_EQ(out.current_station_id, "dock");
}

// 选车请求构建（纯函数）。
//
// 原实现内联在 DispatcherNode::BuildAssignmentRequest 里，混了三件事：
//   1. 刷新车队运行时状态（IO：读订阅、读里程计）
//   2. 按 id 排序保证裁决确定性
//   3. 调 EstimateVehicleApproachCost 补"到取货点的路网成本"
// 其中 2、3 是纯逻辑，但因为没有独立入口，只能通过起 ROS 图来间接验证
// （"同分时谁先被选中"这种确定性属性尤其难以回归）。
//
// 这里把 2、3 抽出来；1 仍留在 ROS 侧（它必须读订阅）。
#pragma once

#include <optional>
#include <string>
#include <unordered_map>
#include <vector>

#include "amr_dispatcher_core/catalog/station_catalog.hpp"
#include "amr_dispatcher_core/fleet/vehicle_assignment.hpp"

namespace amr_dispatcher_core::fleet {

struct VehicleAssignmentRequestInputs {
  // 待选车辆（顺序不限：本函数会重排，保证同分裁决确定）
  std::vector<VehicleRuntimeState> vehicles;
  // 任务侧
  std::string requested_vehicle_id;
  std::string pickup_station_id;
  std::string dropoff_station_id;
  std::string required_capability;
  double min_battery_percent = 0.0;
  int state_max_age_ms = 5000;
  // 路网成本来源；nullptr 或未加载 -> 不填 distance_to_pickup_m
  const catalog::StationCatalog* catalog = nullptr;
  bool catalog_loaded = false;
};

VehicleAssignmentRequest BuildVehicleAssignmentRequest(const VehicleAssignmentRequestInputs& inputs);

// 排序规则单列出来，供调用方复用（例如把候选按同一顺序打日志）。
// 返回按 vehicle_id 字典序排列的下标。
std::vector<std::size_t> StableVehicleOrder(const std::vector<VehicleRuntimeState>& vehicles);

}  // namespace amr_dispatcher_core::fleet

#include "amr_dispatcher_core/fleet/vda5050_link_state.hpp"

#include <gtest/gtest.h>

using namespace amr_dispatcher_core::fleet;
using Clock = std::chrono::steady_clock;

namespace {

Vda5050StateObservation MakeObservation(double x, double y, double battery,
                                        bool position_initialized = true) {
  Vda5050StateObservation o;
  o.position_initialized = position_initialized;
  o.x = x;
  o.y = y;
  o.battery_percent = battery;
  return o;
}

}  // namespace

TEST(Vda5050LinkStateTest, DefaultsAreOptimisticOnline) {
  const Vda5050LinkState state;
  // 乐观初值：online=false 到达前不阻塞派发（与网关 transient_local 重放收敛）
  EXPECT_TRUE(state.online);
  EXPECT_FALSE(state.seen_state);
  EXPECT_FALSE(state.position_valid);
  EXPECT_FALSE(state.quarantined);
  EXPECT_DOUBLE_EQ(state.battery_percent, 100.0);
}

TEST(Vda5050LinkStateTest, StateObservationUpdatesAllFields) {
  Vda5050LinkState state;
  const auto now = Clock::now();
  EXPECT_EQ(ApplyStateObservation(&state, MakeObservation(1.5, -2.0, 77.5), now),
            LinkStateApplyAction::kUpdated);
  EXPECT_TRUE(state.seen_state);
  EXPECT_EQ(state.last_state_time, now);
  EXPECT_TRUE(state.position_valid);
  EXPECT_DOUBLE_EQ(state.position_x, 1.5);
  EXPECT_DOUBLE_EQ(state.position_y, -2.0);
  EXPECT_DOUBLE_EQ(state.battery_percent, 77.5);
}

TEST(Vda5050LinkStateTest, PositionUninitializedMarksInvalid) {
  Vda5050LinkState state;
  ApplyStateObservation(&state, MakeObservation(0.0, 0.0, 50.0,
                                                /*position_initialized=*/false),
                        Clock::now());
  EXPECT_FALSE(state.position_valid);  // 位置不可用 -> 选车不合格
}

// 核心回归（对应 e2e Stage 6.4 当年靠 kill -9 真车才复现的缺陷）：
// 离线期间收到的 state 不得把链路回置成在线。
TEST(Vda5050LinkStateTest, StateWhileOfflineNeverFlipsOnlineBack) {
  Vda5050LinkState state;
  ApplyOnlineReport(&state, false);
  ASSERT_FALSE(state.online);

  const auto action = ApplyStateObservation(&state, MakeObservation(3.0, 4.0, 60.0),
                                            Clock::now());
  EXPECT_EQ(action, LinkStateApplyAction::kUpdatedWhileOffline);
  EXPECT_FALSE(state.online);  // 铁律：仍为离线，派发仍挂起
  // 但数据照常更新：位置/电量是重新核对物理占位的输入
  EXPECT_DOUBLE_EQ(state.position_x, 3.0);
  EXPECT_TRUE(state.seen_state);
}

TEST(Vda5050LinkStateTest, OnlineReportReportsWhetherStateFlipped) {
  Vda5050LinkState state;  // 默认 online=true
  EXPECT_TRUE(ApplyOnlineReport(&state, false));   // true -> false：翻转
  EXPECT_FALSE(state.online);
  EXPECT_FALSE(ApplyOnlineReport(&state, false));  // 重复报文：不翻转
  EXPECT_TRUE(ApplyOnlineReport(&state, true));    // 重连：翻转
  EXPECT_TRUE(state.online);
  EXPECT_FALSE(ApplyOnlineReport(&state, true));   // transient_local 重放：不翻转
}

TEST(Vda5050LinkStateTest, StateStaleOnlyWhenOnlineAndSeen) {
  Vda5050LinkState state;
  const auto now = Clock::now();
  const auto threshold = std::chrono::milliseconds(5000);

  // 从未收到 state：不算陈旧（没有"多久没更新"可比）
  EXPECT_FALSE(IsStateStale(state, now, threshold));

  ApplyStateObservation(&state, MakeObservation(0.0, 0.0, 100.0), now);
  EXPECT_FALSE(IsStateStale(state, now + std::chrono::milliseconds(4999), threshold));
  EXPECT_FALSE(IsStateStale(state, now + threshold, threshold));  // 边界不含
  EXPECT_TRUE(IsStateStale(state, now + std::chrono::milliseconds(5001), threshold));
}

TEST(Vda5050LinkStateTest, OfflineLinkIsNeverReportedStale) {
  // 离线是独立信号（走 kSuspendDispatch），不该再报 stale
  Vda5050LinkState state;
  ApplyStateObservation(&state, MakeObservation(0.0, 0.0, 100.0), Clock::now());
  ApplyOnlineReport(&state, false);
  EXPECT_FALSE(IsStateStale(state, Clock::now() + std::chrono::seconds(60),
                            std::chrono::milliseconds(5000)));
}

TEST(Vda5050LinkStateTest, NullPointerIsTolerated) {
  EXPECT_EQ(ApplyStateObservation(nullptr, MakeObservation(0.0, 0.0, 1.0), Clock::now()),
            LinkStateApplyAction::kUpdated);
  EXPECT_FALSE(ApplyOnlineReport(nullptr, false));
}

TEST(Vda5050LinkStateTest, QuarantineIsIndependentOfOnline) {
  Vda5050LinkState state;
  ApplyOnlineReport(&state, false);
  state.quarantined = true;
  // 隔离 + 离线：两者各自独立，守卫据此判定"已知且已处置"而不冻结全队
  EXPECT_TRUE(state.quarantined);
  EXPECT_FALSE(state.online);
  ApplyOnlineReport(&state, true);
  EXPECT_TRUE(state.quarantined);  // 重新上线不解除隔离（需显式恢复）
  EXPECT_TRUE(state.online);
}

#include "amr_dispatcher_core/fleet/vda5050_link_state.hpp"

namespace amr_dispatcher_core::fleet {

LinkStateApplyAction ApplyStateObservation(
    Vda5050LinkState* state, const Vda5050StateObservation& observation,
    std::chrono::steady_clock::time_point now) {
  if (state == nullptr) {
    return LinkStateApplyAction::kUpdated;
  }
  state->seen_state = true;
  state->last_state_time = now;
  state->position_valid = observation.position_initialized;
  state->position_x = observation.x;
  state->position_y = observation.y;
  state->battery_percent = observation.battery_percent;
  // 离线期间收到 state 绝不可回置 online（见头文件铁律）：只更新数据。
  return state->online ? LinkStateApplyAction::kUpdated
                       : LinkStateApplyAction::kUpdatedWhileOffline;
}

bool ApplyOnlineReport(Vda5050LinkState* state, bool online) {
  if (state == nullptr) {
    return false;
  }
  if (state->online == online) {
    return false;  // 状态未变（transient_local 重放/重复报文）：调用方不重复告警
  }
  state->online = online;
  return true;
}

bool IsStateStale(const Vda5050LinkState& state, std::chrono::steady_clock::time_point now,
                  std::chrono::milliseconds stale_threshold) {
  if (!state.online || !state.seen_state) {
    return false;  // 从未收到 state 的在线车没有"多久没更新"可比
  }
  return (now - state.last_state_time) > stale_threshold;
}

}  // namespace amr_dispatcher_core::fleet

