1754	void DispatcherNode::ScheduleTick() {
1755	  // 已受理的 ExecuteMission action 取消需在提前返回之前处理（10Hz 延迟 ≤100ms）
1756	  ProcessActionCancels();
1757	
1758	  // 批次 2：防抖状态落盘。放在所有提前 return 之前，保证即使队列空/门禁
1759	  // 阻断也照样把"已变更"的状态写下去（否则最后一次变更可能永远不落盘）。
1760	  if (state_snapshot_dirty_ && !state_snapshot_file_.empty()) {
1761	    const auto elapsed = std::chrono::duration<double>(
1762	                             std::chrono::steady_clock::now() - state_snapshot_dirty_at_)
1763	                             .count();
1764	    if (elapsed >= state_snapshot_debounce_sec_) {
1765	      FlushStateSnapshot();
1766	    }
1767	  }
1768	
1769	  // Task 5 Rule 2（Spec §5.2）：每 tick 先巡检受管小车链路。
1770	  // 离线 -> 挂起新派发（不消费 queue_start_requested_，恢复后自动继续）、
1771	  // 锁一律保留；在线但 state 陈旧 -> 仅软看门狗告警。受管清单为空时零开销跳过。
1772	  if (EnforceVda5050LinkGuard()) {
1773	    return;
1774	  }
1775	
1776	  if (!queue_ || queue_->empty()) {
1777	    return;
1778	  }
1779	  const std::size_t max_active = get_parameter("max_active_missions").as_int();
1780	  if (active_missions_.size() >= max_active) {
1781	    return;
1782	  }
1783	
1784	  // 执行模型：每台受管车同时只跑一条 /plan（多车则可并发多条）。
1785	  // 无可用执行槽位 -> 本 tick 不派发（任务留队，等某台车完成或状态变化后重试）。
1786	  if (!HasFreeVehicleSlot()) {
1787	    return;
1788	  }
1789	
1790	  // 地图版本门禁：配置了期望哈希且目录已加载时，
1791	  // 若目录哈希缺失，或与期望哈希不一致，均判定为环境地图与部署目录不匹配——暂停出队派发。
1792	  // 直接 return（不消费 queue_start_requested_），哈希恢复一致后派发自动继续。
1793	  map_version_valid_ = true;
1794	  if (!expected_map_hash_.empty() && catalog_reloader_ != nullptr &&
1795	      catalog_reloader_->loaded()) {
1796	    const auto& catalog = catalog_reloader_->catalog();
1797	    if (catalog.map_hash.empty() || catalog.map_hash != expected_map_hash_) {
1798	      map_version_valid_ = false;
1799	      RCLCPP_WARN_THROTTLE(get_logger(), *get_clock(), 10000,
1800	                           "Map hash mismatch: expected %s, got %s, dispatching paused",
1801	                           expected_map_hash_.c_str(),
1802	                           catalog.map_hash.empty() ? "<missing>" : catalog.map_hash.c_str());
1803	      return;
1804	    }
1805	  }
1806	
1807	  // 行为树出队派发门控：runtime 树按"空闲 + 启动请求"给派发决策，
1808	  // 未请求启动时即使队列有任务也不出队（启动请求由提单/入队/结果链武装）。
1809	  amr_dispatcher_bt::MissionRuntimeBehaviorTreeInput runtime_input;
1810	  runtime_input.tick.mission_active = !HasFreeVehicleSlot();
1811	  runtime_input.tick.queue_start_requested = queue_start_requested_;
1812	  const auto runtime_result = amr_dispatcher_bt::TickMissionRuntimeBehaviorTree(runtime_input);
1813	  if (!runtime_result.success || !runtime_result.decision.start_queued_mission) {
1814	    return;
1815	  }
1816	  queue_start_requested_ = false;  // 启动请求被本次派发消费
1817	
1818	  // ---- A6 选车（PeekN 扫描 + 三态处理 + 队首阻塞规避）----
1819	  // 队首任务可能因"暂无合格车辆"而不可派；此时**不能**让整条队列堵死：
1820	  // 扫描前 N 个排队任务，挑第一个能选到车且能预留锁的。
1821	  const int64_t scan_depth_param =
1822	      std::max<int64_t>(1, get_parameter("assignment_scan_depth").as_int());
1823	  const std::size_t scan_depth = static_cast<std::size_t>(scan_depth_param);
1824	  const auto candidates = queue_->PeekN(scan_depth);
1825	  if (candidates.empty()) {
1826	    return;  // 队列任务全部暂停：与 PopNext 失败等价，本 tick 结束
1827	  }
1828	
1829	  struct Candidate {
1830	    amr_dispatcher_core::dispatcher::Mission mission;
1831	    std::string vehicle_id;
1832	    std::vector<std::string> route_locks;
1833	  };
1834	  std::vector<Candidate> ready;         // 选到车 + 预留成功的候选（按队列顺序）
1835	  bool saw_deferred = false;
1836	  bool saw_indeterminate = false;
1837	  std::string deferred_reason;
1838	  std::string indeterminate_reason;
1839	
1840	  for (const auto& candidate_mission : candidates) {
1841	    // 1) 选车（三态）
1842	    // 兼容红线：**legacy 单车模式**（既无 local_sim 受管车、也无 VDA 5050 受管车）
1843	    // 不走选车流程 —— 那里没有"车辆"概念，唯一的执行槽位是空串键
1844	    // （vehicle_current_mission_[""]），与改动前逐字等价。
1845	    // 若此处也调选车，request.vehicles 为空 -> 核心返回 kRejected
1846	    // ("no managed vehicles configured") -> 单车任务被永久判负（实测踩过）。
1847	    amr_dispatcher_core::fleet::VehicleAssignmentDecision decision;
1848	    if (HasAnyManagedVehicle()) {
1849	      decision = SelectVehicleForMission(candidate_mission);
1850	    } else {
1851	      decision.outcome = amr_dispatcher_core::fleet::AssignmentOutcome::kAssigned;
1852	      decision.strategy = "legacy_single_vehicle";
1853	    }
1854	    // 三态 -> 调度动作的映射写死在纯函数里（可单测，A7）：
1855	    // kDeferred 留队 / kIndeterminate 暂停自动分配 / kRejected 判负。
1856	    const auto dispatch_decision = DecideAssignmentDispatch(decision);
1857	    if (dispatch_decision.action == AssignmentDispatchAction::kStayQueued) {
1858	      saw_deferred = true;
1859	      deferred_reason = dispatch_decision.reason;
1860	      continue;  // 留队等待，下个 tick 重试
1861	    }
1862	    if (dispatch_decision.action == AssignmentDispatchAction::kPauseAutoAssignment) {
1863	      saw_indeterminate = true;
1864	      indeterminate_reason = dispatch_decision.reason;
1865	      continue;  // 状态不确定：暂停自动分配
1866	    }
1867	    if (dispatch_decision.action == AssignmentDispatchAction::kReject) {
1868	      // 永久不满足 -> 该单判负（不静默改派）
1869	      RCLCPP_WARN(get_logger(), "Queued mission %s rejected by vehicle selection: %s",
1870	                  candidate_mission.id.c_str(), dispatch_decision.reason.c_str());
1871	      if (queue_->Cancel(candidate_mission.id)) {
1872	        RejectedQueuedMission(candidate_mission, dispatch_decision.reason);
1873	      }
1874	      continue;
1875	    }
1876	    // 2) 预留路由锁（Peek→Reserve→Pop 原子链：预留成功才出队）
1877	    //    time_space 模式：预约**带时间窗**的路权（多车可错峰并行），
1878	    //    整条路径全有或全无；static 模式：静态排他锁（现网行为）。
1879	    std::vector<std::string> route_locks;
1880	    if (catalog_reloader_ != nullptr && catalog_reloader_->loaded()) {
1881	      route_locks = amr_dispatcher_core::workflow::PlanMissionRouteLocks(
1882	          catalog_reloader_->catalog(), candidate_mission.pickup_station,
1883	          candidate_mission.dropoff_station);
1884	    }
1885	    if (UseTimeSpaceMode()) {
1886	      // 时空窗模式：不占静态排他锁，改为预约时间窗。
1887	      std::vector<std::string> path_node_ids;
1888	      if (catalog_reloader_ != nullptr && catalog_reloader_->loaded() &&
1889	          !candidate_mission.pickup_station.empty()) {
1890	        const auto route_path = amr_dispatcher_core::catalog::FindRoutePath(
1891	            catalog_reloader_->catalog(), candidate_mission.pickup_station,
1892	            candidate_mission.dropoff_station);
1893	        if (route_path.has_value()) {
1894	          path_node_ids = *route_path;
1895	        }
1896	      }
1897	      std::string ts_message;
1898	      if (!ReserveTimeSpaceForMission(candidate_mission.id, path_node_ids, &ts_message)) {
1899	        RCLCPP_WARN(get_logger(),
1900	                    "Time-space reservation denied for queued mission %s: %s",
1901	                    candidate_mission.id.c_str(), ts_message.c_str());
1902	        pending_wait_[candidate_mission.id] = route_locks;
1903	        continue;  // 留队等待（换下一个候选）
1904	      }
1905	      // 时空模式下不占静态排他锁：route_locks 仅作记账用途
1906	      route_locks.clear();
1907	    }
1908	    if (!UseTimeSpaceMode() && !route_locks.empty() && reservation_table_) {
1909	      auto reserve = reservation_table_->Reserve(candidate_mission.id, route_locks);
1910	      if (!reserve.success) {
1911	        // 锁被占 -> 该单等锁（留队）；**不占用启动请求**，等锁释放时重试。
1912	        pending_wait_[candidate_mission.id] = route_locks;
1913	        RCLCPP_WARN(get_logger(), "Reservation denied for queued mission %s: %s",
1914	                    candidate_mission.id.c_str(), reserve.message.c_str());
1915	        if (event_pub_ && event_pub_->is_activated()) {
1916	          amr_dispatcher_interfaces::msg::MissionEvent msg;
1917	          msg.stamp = now();
1918	          msg.mission_id = candidate_mission.id;
1919	          msg.order_id = candidate_mission.order_id;
1920	          msg.event = "reservation_denied";
1921	          msg.from_state = "PENDING";
1922	          msg.to_state = "PENDING";  // 任务留在队列，状态不变
1923	          msg.reason = reserve.message;
1924	          event_pub_->publish(msg);
1925	        }
1926	        if (event_log_) {
1927	          amr_dispatcher_core::dispatcher::MissionEvent evt;
1928	          evt.stamp = "now";
1929	          evt.mission_id = candidate_mission.id;
1930	          evt.event = "reservation_denied";
1931	          evt.message = reserve.message;
1932	          event_log_->Append(evt);
1933	        }
1934	        continue;  // 换下一个候选（队首阻塞规避）
1935	      }
1936	      mission_reserved_at_[candidate_mission.id] = std::chrono::steady_clock::now();
1937	    }
1938	    pending_wait_.erase(candidate_mission.id);
1939	    Candidate ready_candidate;
1940	    ready_candidate.mission = candidate_mission;
1941	    ready_candidate.vehicle_id = decision.vehicle_id;
1942	    ready_candidate.route_locks = std::move(route_locks);
1943	    ready.push_back(std::move(ready_candidate));
1944	    break;  // 本 tick 只派一个（保持"一次一个"的节奏与可观测性）
1945	  }
1946	
1947	  if (ready.empty()) {
1948	    if (saw_indeterminate) {
1949	      // 状态不确定 -> 暂停自动分配（不消费启动请求，等状态恢复自动继续）
1950	      auto_assignment_paused_ = true;
1951	      RCLCPP_WARN_THROTTLE(get_logger(), *get_clock(), 5000,
1952	                           "Auto vehicle assignment paused: %s", indeterminate_reason.c_str());
1953	      ReArmQueueStartRequest();
1954	    } else if (saw_deferred) {
1955	      RCLCPP_WARN_THROTTLE(get_logger(), *get_clock(), 5000,
1956	                           "Vehicle assignment deferred, mission stays queued: %s",
1957	                           deferred_reason.c_str());
1958	      ReArmQueueStartRequest();  // 留队等待，下个 tick 重试
1959	    }
1960	    return;
1961	  }
1962	  auto_assignment_paused_ = false;
1963	
1964	  const std::string candidate_id = ready.front().mission.id;
1965	  const std::string candidate_order_id = ready.front().mission.order_id;
1966	  std::vector<std::string> route_locks = std::move(ready.front().route_locks);
1967	  const std::string dispatch_vehicle_id = ready.front().vehicle_id;
1968	  // 执行后端（评审 P0.1）：VDA 5050 车自带控制器，不走本地 /plan 运动链。
1969	  const bool is_vda5050_dispatch =
1970	      std::find(vda5050_vehicle_ids_.begin(), vda5050_vehicle_ids_.end(),
1971	                dispatch_vehicle_id) != vda5050_vehicle_ids_.end();
1972	
1973	  auto pop = queue_->PopById(candidate_id);
1974	  if (!pop.success || !pop.mission) {
1975	    // 出队失败（任务已被取消/暂停）：释放刚预留的锁，保持原子性
1976	    if (reservation_table_) {
1977	      reservation_table_->Release(candidate_id);
1978	    }
1979	    ReArmQueueStartRequest();
1980	    return;
1981	  }
1982	
1983	  amr_dispatcher_core::dispatcher::Mission m = *pop.mission;
1984	  m.state = amr_dispatcher_core::dispatcher::MissionState::kActive;
1985	  m.assigned_vehicle_id = dispatch_vehicle_id;  // 落定承接车辆（审计用）
1986	  MarkStateDirty();  // 出队派发：排队集与在途集都变了
1987	
1988	  // 解析起终点：无 pickup 时用车辆当前位姿作起点；站点缺失或目录未加载直接判负
1989	  const amr_dispatcher_core::catalog::Station* from_st = nullptr;
1990	  const amr_dispatcher_core::catalog::Station* to_st = nullptr;
1991	  const bool catalog_loaded =
1992	      catalog_reloader_ != nullptr && catalog_reloader_->loaded();
1993	  if (catalog_loaded) {
1994	    const auto& catalog = catalog_reloader_->catalog();
1995	    if (!m.pickup_station.empty()) {
1996	      from_st = amr_dispatcher_core::catalog::FindStation(catalog, m.pickup_station);
1997	    }
1998	    if (!m.dropoff_station.empty()) {
1999	      to_st = amr_dispatcher_core::catalog::FindStation(catalog, m.dropoff_station);
2000	    }
2001	  }
2002	  if (m.dropoff_station.empty() || !to_st) {
2003	    RCLCPP_WARN(get_logger(), "Mission %s has no resolvable dropoff station (%s, catalog_loaded=%d), failing",
2004	                m.id.c_str(), m.dropoff_station.c_str(), catalog_loaded);
2005	    if (event_pub_ && event_pub_->is_activated()) {
2006	      amr_dispatcher_interfaces::msg::MissionEvent msg;
2007	      msg.stamp = now();
2008	      msg.mission_id = m.id;
2009	      msg.order_id = m.order_id;
2010	      msg.event = "plan_failed";
2011	      msg.to_state = "FAILED";
2012	      msg.reason = "unknown dropoff station: " + m.dropoff_station;
2013	      event_pub_->publish(msg);
2014	    }
2015	    // 本单已出队但被判负丢弃：Peek 阶段预留的路由锁须就地释放
2016	    //（任务不进 active_missions_，走不到 Complete/Fail 的终态清理）
2017	    if (reservation_table_) {
2018	      reservation_table_->Release(m.id);
2019	    }
2020	    ForgetMissionDispatchState(m.id);
2021	    // ExecuteMission goal 须就地 abort：该分支不经 Complete/Fail，不收口则
2022	    // action 客户端永久悬挂、handle 残留在 execute_goal_handles_（终审 F8）
