1841	std::optional<DispatcherNode::ReadyCandidate> DispatcherNode::SelectReadyCandidate() {
1842	  // ---- A6 选车（PeekN 扫描 + 三态处理 + 队首阻塞规避）----
1843	  // 队首任务可能因"暂无合格车辆"而不可派；此时**不能**让整条队列堵死：
1844	  // 扫描前 N 个排队任务，挑第一个能选到车且能预留锁的。
1845	  const int64_t scan_depth_param =
1846	      std::max<int64_t>(1, get_parameter("assignment_scan_depth").as_int());
1847	  const std::size_t scan_depth = static_cast<std::size_t>(scan_depth_param);
1848	  const auto candidates = queue_->PeekN(scan_depth);
1849	  if (candidates.empty()) {
1850	    return std::nullopt;  // 队列任务全部暂停：与 PopNext 失败等价，本 tick 结束
1851	  }
1852	
1853	  std::optional<ReadyCandidate> ready;  // 选到车 + 预留成功的候选（本 tick 只取一个）
1854	  bool saw_deferred = false;
1855	  bool saw_indeterminate = false;
1856	  std::string deferred_reason;
1857	  std::string indeterminate_reason;
1858	
1859	  for (const auto& candidate_mission : candidates) {
1860	    // 1) 选车（三态）
1861	    // 兼容红线：**legacy 单车模式**（既无 local_sim 受管车、也无 VDA 5050 受管车）
1862	    // 不走选车流程 —— 那里没有"车辆"概念，唯一的执行槽位是空串键
1863	    // （vehicle_current_mission_[""]），与改动前逐字等价。
1864	    // 若此处也调选车，request.vehicles 为空 -> 核心返回 kRejected
1865	    // ("no managed vehicles configured") -> 单车任务被永久判负（实测踩过）。
1866	    amr_dispatcher_core::fleet::VehicleAssignmentDecision decision;
1867	    if (HasAnyManagedVehicle()) {
1868	      decision = SelectVehicleForMission(candidate_mission);
1869	    } else {
1870	      decision.outcome = amr_dispatcher_core::fleet::AssignmentOutcome::kAssigned;
1871	      decision.strategy = "legacy_single_vehicle";
1872	    }
1873	    // 三态 -> 调度动作的映射写死在纯函数里（可单测，A7）：
1874	    // kDeferred 留队 / kIndeterminate 暂停自动分配 / kRejected 判负。
1875	    const auto dispatch_decision = DecideAssignmentDispatch(decision);
1876	    if (dispatch_decision.action == AssignmentDispatchAction::kStayQueued) {
1877	      saw_deferred = true;
1878	      deferred_reason = dispatch_decision.reason;
1879	      continue;  // 留队等待，下个 tick 重试
1880	    }
1881	    if (dispatch_decision.action == AssignmentDispatchAction::kPauseAutoAssignment) {
1882	      saw_indeterminate = true;
1883	      indeterminate_reason = dispatch_decision.reason;
1884	      continue;  // 状态不确定：暂停自动分配
1885	    }
1886	    if (dispatch_decision.action == AssignmentDispatchAction::kReject) {
1887	      // 永久不满足 -> 该单判负（不静默改派）
1888	      RCLCPP_WARN(get_logger(), "Queued mission %s rejected by vehicle selection: %s",
1889	                  candidate_mission.id.c_str(), dispatch_decision.reason.c_str());
1890	      if (queue_->Cancel(candidate_mission.id)) {
1891	        RejectedQueuedMission(candidate_mission, dispatch_decision.reason);
1892	      }
1893	      continue;
1894	    }
1895	    // 2) 预留路由锁（Peek→Reserve→Pop 原子链：预留成功才出队）
1896	    //    time_space 模式：预约**带时间窗**的路权（多车可错峰并行），
1897	    //    整条路径全有或全无；static 模式：静态排他锁（现网行为）。
1898	    std::vector<std::string> route_locks;
1899	    if (catalog_reloader_ != nullptr && catalog_reloader_->loaded()) {
1900	      route_locks = amr_dispatcher_core::workflow::PlanMissionRouteLocks(
1901	          catalog_reloader_->catalog(), candidate_mission.pickup_station,
1902	          candidate_mission.dropoff_station);
1903	    }
1904	    if (UseTimeSpaceMode()) {
1905	      // 时空窗模式：不占静态排他锁，改为预约时间窗。
1906	      std::vector<std::string> path_node_ids;
1907	      if (catalog_reloader_ != nullptr && catalog_reloader_->loaded() &&
1908	          !candidate_mission.pickup_station.empty()) {
1909	        const auto route_path = amr_dispatcher_core::catalog::FindRoutePath(
1910	            catalog_reloader_->catalog(), candidate_mission.pickup_station,
1911	            candidate_mission.dropoff_station);
1912	        if (route_path.has_value()) {
1913	          path_node_ids = *route_path;
1914	        }
1915	      }
1916	      std::string ts_message;
1917	      if (!ReserveTimeSpaceForMission(candidate_mission.id, path_node_ids, &ts_message)) {
1918	        RCLCPP_WARN(get_logger(),
1919	                    "Time-space reservation denied for queued mission %s: %s",
1920	                    candidate_mission.id.c_str(), ts_message.c_str());
1921	        pending_wait_[candidate_mission.id] = route_locks;
1922	        continue;  // 留队等待（换下一个候选）
1923	      }
1924	      // 时空模式下不占静态排他锁：route_locks 仅作记账用途
1925	      route_locks.clear();
1926	    }
1927	    if (!UseTimeSpaceMode() && !route_locks.empty() && reservation_table_) {
1928	      auto reserve = reservation_table_->Reserve(candidate_mission.id, route_locks);
1929	      if (!reserve.success) {
1930	        // 锁被占 -> 该单等锁（留队）；**不占用启动请求**，等锁释放时重试。
1931	        pending_wait_[candidate_mission.id] = route_locks;
1932	        RCLCPP_WARN(get_logger(), "Reservation denied for queued mission %s: %s",
1933	                    candidate_mission.id.c_str(), reserve.message.c_str());
1934	        if (event_pub_ && event_pub_->is_activated()) {
1935	          amr_dispatcher_interfaces::msg::MissionEvent msg;
1936	          msg.stamp = now();
1937	          msg.mission_id = candidate_mission.id;
1938	          msg.order_id = candidate_mission.order_id;
1939	          msg.event = "reservation_denied";
1940	          msg.from_state = "PENDING";
1941	          msg.to_state = "PENDING";  // 任务留在队列，状态不变
1942	          msg.reason = reserve.message;
1943	          event_pub_->publish(msg);
1944	        }
1945	        if (event_log_) {
1946	          amr_dispatcher_core::dispatcher::MissionEvent evt;
1947	          evt.stamp = "now";
1948	          evt.mission_id = candidate_mission.id;
1949	          evt.event = "reservation_denied";
1950	          evt.message = reserve.message;
1951	          event_log_->Append(evt);
1952	        }
1953	        continue;  // 换下一个候选（队首阻塞规避）
1954	      }
1955	      mission_reserved_at_[candidate_mission.id] = std::chrono::steady_clock::now();
1956	    }
1957	    pending_wait_.erase(candidate_mission.id);
1958	    ReadyCandidate ready_candidate;
1959	    ready_candidate.mission = candidate_mission;
1960	    ready_candidate.vehicle_id = decision.vehicle_id;
1961	    ready_candidate.route_locks = std::move(route_locks);
1962	    ready = std::move(ready_candidate);
1963	    break;  // 本 tick 只派一个（保持"一次一个"的节奏与可观测性）
1964	  }
1965	
1966	  if (!ready.has_value()) {
1967	    if (saw_indeterminate) {
1968	      // 状态不确定 -> 暂停自动分配（不消费启动请求，等状态恢复自动继续）
1969	      auto_assignment_paused_ = true;
1970	      RCLCPP_WARN_THROTTLE(get_logger(), *get_clock(), 5000,
1971	                           "Auto vehicle assignment paused: %s", indeterminate_reason.c_str());
1972	      ReArmQueueStartRequest();
