                           "Vehicle assignment deferred, mission stays queued: %s",
                           deferred_reason.c_str());
      ReArmQueueStartRequest();  // 留队等待，下个 tick 重试
    }
    return std::nullopt;
  }
  auto_assignment_paused_ = false;
  return ready;
}

