// 死锁绕行决策（纯函数）。
//
// 触发面收窄（显式写死，可单测）：
//   * 只对 `DeadlockKind::kMutualBlock`（WFG 环）触发绕行；
//     kIdleActive / kLongReservationHold 仍走既有的 retry/pause，
//     kOverCapacity 维持 kNone（过载不是互斥冲突，绕行无意义）。
//   * 受阻边 = 成环路径里**奇数位**资源中 `route_edge:*` 的项；
//     `route_node:*` 不解成边——节点冲突不代表整条边不可用。
//   * 新路径必须**真的不同**才算绕行；否则 kNoAlternative（不假装成功）。
//
// 本模块只做决策；落地顺序由 PlanDeadlockRerouteCommit 给出，铁律是
// **新路预约成功之后**才允许释放旧资源——"先释放旧资源、再发现新路线约不上"
// 会瞬间把两单都放在同一段路上（用户明确指出的风险点）。
#pragma once

#include <cstddef>
#include <string>
#include <unordered_set>
#include <vector>

#include "amr_dispatcher_core/catalog/station_catalog.hpp"

namespace amr_dispatcher_core::workflow {

struct RerouteRequest {
  std::string mission_id;
  // 该单当前行驶的节点序列（行驶序）
  std::vector<std::string> current_path;
  // 受阻边资源键（`route_edge:<lo>__<hi>`），一般来自 BlockedEdgeKeysFromCycle
  std::unordered_set<std::string> blocked_edge_keys;
  // 寻路目录；nullptr 或未加载时不可能给出替代路线
  const catalog::StationCatalog* catalog = nullptr;
  bool catalog_loaded = false;
  std::string pickup_station;
  std::string dropoff_station;
  std::size_t attempt = 0;
  std::size_t max_attempts = 1;  // 默认只试一次
};

struct RerouteDecision {
  enum class Kind {
    kNoReroute,     // 不该绕行（无目录 / 无受阻边 / 已达尝试上限）
    kRerouteReady,  // 有替代路线：new_path / new_route_locks 可用
    kNoAlternative, // 所有路线都不可达，或替代路线与当前一致
    kExhausted,     // 尝试次数用尽
  };
  Kind kind = Kind::kNoReroute;
  std::vector<std::string> new_path;
  std::vector<std::string> new_route_locks;
  // 失败原因（写进事件日志用；成功时为空）
  std::string reason;
};

// 从成环路径（任务与资源交替、偶数位任务、奇数位资源）里取受阻边键。
// 只收 `route_edge:` 前缀的项，且原样保留（调用方需传规范化键）。
std::unordered_set<std::string> BlockedEdgeKeysFromCycle(
    const std::vector<std::string>& cycle_path);

RerouteDecision PlanDeadlockReroute(const RerouteRequest& request);

// 绕行落地顺序（纯函数）：只有新路预约成功，才允许释放旧锁并重发路径。
// 预约失败 -> 两个动作都为 false，调用方必须保持旧锁与旧路线不动。
struct RerouteCommitDecision {
  bool release_old_locks = false;
  bool republish_path = false;
  std::string reason;
};
RerouteCommitDecision PlanDeadlockRerouteCommit(const RerouteDecision& decision,
                                                bool new_reservation_ok);

}  // namespace amr_dispatcher_core::workflow

