#include "amr_dispatcher_core/workflow/deadlock_reroute.hpp"

#include "amr_dispatcher_core/dispatcher/traffic_reservation.hpp"

namespace amr_dispatcher_core::workflow {

std::unordered_set<std::string> BlockedEdgeKeysFromCycle(
    const std::vector<std::string>& cycle_path) {
  std::unordered_set<std::string> blocked;
  // 成环路径形如 [m1, res_a, m2, res_b, m1]：奇数位是资源
  for (std::size_t i = 1; i < cycle_path.size(); i += 2) {
    const std::string& resource = cycle_path[i];
    const std::string prefix = "route_edge:";
    if (resource.compare(0, prefix.size(), prefix) == 0) {
      blocked.insert(resource);
    }
  }
  return blocked;
}

RerouteDecision PlanDeadlockReroute(const RerouteRequest& request) {
  RerouteDecision decision;
  if (request.attempt >= request.max_attempts) {
    decision.kind = RerouteDecision::Kind::kExhausted;
    decision.reason = "reroute attempts exhausted";
    return decision;
  }
  if (!request.catalog_loaded || request.catalog == nullptr) {
    decision.kind = RerouteDecision::Kind::kNoReroute;
    decision.reason = "station catalog not loaded";
    return decision;
  }
  if (request.blocked_edge_keys.empty()) {
    decision.kind = RerouteDecision::Kind::kNoReroute;
    decision.reason = "no blocked edge in deadlock cycle";
    return decision;
  }
  if (request.pickup_station.empty() || request.dropoff_station.empty()) {
    // 无起终点就无法重算行驶序（车辆当前位姿作起点的情况不在此列：
    // 那种任务本身没有可绕的拓扑路线）
    decision.kind = RerouteDecision::Kind::kNoReroute;
    decision.reason = "mission has no pickup/dropoff stations";
    return decision;
  }

  const auto alternative = catalog::FindRoutePathAvoiding(
      *request.catalog, request.pickup_station, request.dropoff_station,
      request.blocked_edge_keys);
  if (!alternative.has_value()) {
    // 不伪造直线路径：明确告知无替代路线，由调用方回退到 retry/pause
    decision.kind = RerouteDecision::Kind::kNoAlternative;
    decision.reason = "no alternative route avoiding blocked edges";
    return decision;
  }
  if (*alternative == request.current_path) {
    decision.kind = RerouteDecision::Kind::kNoAlternative;
    decision.reason = "alternative route identical to current path";
    return decision;
  }
  decision.kind = RerouteDecision::Kind::kRerouteReady;
  decision.new_path = *alternative;
  // 与新路径同源的锁集：与派发阶段用同一个 BuildLockIds（含路口节点锁），
  // 保证"绕行后持有的锁"与"预约时算出的锁"是同一套资源。
  decision.new_route_locks = dispatcher::ResourceTable::BuildLockIds(
      decision.new_path, /*include_intersection_locks=*/true);
  return decision;
}

RerouteCommitDecision PlanDeadlockRerouteCommit(const RerouteDecision& decision,
                                                bool new_reservation_ok) {
  RerouteCommitDecision commit;
  if (decision.kind != RerouteDecision::Kind::kRerouteReady) {
    commit.reason = "no reroute ready";
    return commit;
  }
  if (!new_reservation_ok) {
    // 关键：新路约不上时**不动旧资源、不重发路线**（否则两单同时落在旧路线上）
    commit.reason = "new route reservation failed; keeping current route and locks";
    return commit;
  }
  commit.release_old_locks = true;
  commit.republish_path = true;
  return commit;
}

}  // namespace amr_dispatcher_core::workflow

