// 死锁绕行决策的验收（批次 4.4 场景表）。
//
// 覆盖用户点名的四个场景里与决策直接相关的三个：
//   * 存在两条可达路线，其中一条边被禁用 -> 选替代路线
//   * 所有路线均不可达 -> 明确失败原因，不伪造直线路径
//   * 替代路线的资源预约失败 -> 不下发新路线、不释放原有资源
// 另加"绕行使能条件"（非 WFG 环 / 无受阻边 / 目录未加载 / 尝试用尽）。
#include "amr_dispatcher_core/workflow/deadlock_reroute.hpp"

#include <gtest/gtest.h>

using amr_dispatcher_core::catalog::CatalogStationEdge;
using amr_dispatcher_core::catalog::RoadNode;
using amr_dispatcher_core::catalog::Station;
using amr_dispatcher_core::catalog::StationCatalog;
using amr_dispatcher_core::workflow::BlockedEdgeKeysFromCycle;
using amr_dispatcher_core::workflow::PlanDeadlockReroute;
using amr_dispatcher_core::workflow::PlanDeadlockRerouteCommit;
using amr_dispatcher_core::workflow::RerouteDecision;
using amr_dispatcher_core::workflow::RerouteRequest;

namespace {

// pickup_A --(3m 直连)--> dropoff_B
//      \--(2m)-- n1 --(2m)--^
StationCatalog MakeCatalog() {
  StationCatalog catalog;
  catalog.stations.push_back(Station{"pickup_A", "map", 0.0, 0.0, 0.0});
  catalog.stations.push_back(Station{"dropoff_B", "map", 10.0, 0.0, 0.0});
  catalog.road_nodes.push_back(RoadNode{"n1", "map", 5.0, 5.0, 0.0});
  catalog.edges.push_back(CatalogStationEdge{"pickup_A", "dropoff_B", 3.0, true, true});
  catalog.edges.push_back(CatalogStationEdge{"pickup_A", "n1", 2.0, true, true});
  catalog.edges.push_back(CatalogStationEdge{"n1", "dropoff_B", 2.0, true, true});
  return catalog;
}

RerouteRequest MakeRequest(const StationCatalog& catalog,
                           std::unordered_set<std::string> blocked) {
  RerouteRequest request;
  request.mission_id = "m1";
  request.current_path = {"pickup_A", "dropoff_B"};
  request.blocked_edge_keys = std::move(blocked);
  request.catalog = &catalog;
  request.catalog_loaded = true;
  request.pickup_station = "pickup_A";
  request.dropoff_station = "dropoff_B";
  return request;
}

}  // namespace

TEST(DeadlockRerouteTest, CycleYieldsOnlyEdgeKeys) {
  // 成环路径：任务与资源交替，奇数位是资源
  const std::vector<std::string> cycle{"m1", "route_edge:pickup_A__dropoff_B", "m2",
                                       "route_node:n1", "m1"};
  const auto blocked = BlockedEdgeKeysFromCycle(cycle);
  ASSERT_EQ(blocked.size(), 1u);
  EXPECT_EQ(blocked.count("route_edge:pickup_A__dropoff_B"), 1u);
  EXPECT_EQ(blocked.count("route_node:n1"), 0u);  // 节点冲突不解成边
}

TEST(DeadlockRerouteTest, CycleWithoutEdgeYieldsNothing) {
  const std::vector<std::string> cycle{"m1", "route_node:a", "m2", "route_node:b", "m1"};
  EXPECT_TRUE(BlockedEdgeKeysFromCycle(cycle).empty());
}

// 场景 1：直连边被封 -> 选绕行路线，并给出与新路径同源的锁集。
TEST(DeadlockRerouteTest, BlockedEdgeSelectsAlternativeRoute) {
  const StationCatalog catalog = MakeCatalog();
  const auto decision = PlanDeadlockReroute(
      MakeRequest(catalog, {"route_edge:dropoff_B__pickup_A"}));
  ASSERT_EQ(decision.kind, RerouteDecision::Kind::kRerouteReady);
  EXPECT_EQ(decision.new_path,
            (std::vector<std::string>{"pickup_A", "n1", "dropoff_B"}));
  // 锁集 = 节点锁 + 边锁（与派发阶段同一个 BuildLockIds）
  EXPECT_NE(std::find(decision.new_route_locks.begin(), decision.new_route_locks.end(),
                      "route_edge:n1__pickup_A"),
            decision.new_route_locks.end());
  EXPECT_NE(std::find(decision.new_route_locks.begin(), decision.new_route_locks.end(),
                      "route_edge:dropoff_B__n1"),
            decision.new_route_locks.end());
  EXPECT_NE(std::find(decision.new_route_locks.begin(), decision.new_route_locks.end(),
                      "route_node:n1"),
            decision.new_route_locks.end());
  EXPECT_TRUE(decision.reason.empty());
}

// 场景 2：全部路线不可达 -> 明确失败原因，**不伪造路径**。
TEST(DeadlockRerouteTest, NoAlternativeReportsReason) {
  const StationCatalog catalog = MakeCatalog();
  const auto decision = PlanDeadlockReroute(MakeRequest(
      catalog, {"route_edge:dropoff_B__pickup_A", "route_edge:n1__pickup_A",
                "route_edge:dropoff_B__n1"}));
  EXPECT_EQ(decision.kind, RerouteDecision::Kind::kNoAlternative);
  EXPECT_TRUE(decision.new_path.empty());
  EXPECT_TRUE(decision.new_route_locks.empty());
  EXPECT_EQ(decision.reason, "no alternative route avoiding blocked edges");
}

// 场景 3（关键）：新路预约失败时，两个落地动作都必须为 false ——
// 保持旧锁、不重发路线。
TEST(DeadlockRerouteTest, ReservationFailureKeepsOriginalLocks) {
  const StationCatalog catalog = MakeCatalog();
  const auto decision = PlanDeadlockReroute(
      MakeRequest(catalog, {"route_edge:dropoff_B__pickup_A"}));
  ASSERT_EQ(decision.kind, RerouteDecision::Kind::kRerouteReady);

  const auto failed = PlanDeadlockRerouteCommit(decision, /*new_reservation_ok=*/false);
  EXPECT_FALSE(failed.release_old_locks);
  EXPECT_FALSE(failed.republish_path);
  EXPECT_FALSE(failed.reason.empty());

  const auto committed = PlanDeadlockRerouteCommit(decision, /*new_reservation_ok=*/true);
  EXPECT_TRUE(committed.release_old_locks);
  EXPECT_TRUE(committed.republish_path);
}

TEST(DeadlockRerouteTest, CommitWithoutRerouteDoesNothing) {
  RerouteDecision decision;  // kNoReroute
  const auto commit = PlanDeadlockRerouteCommit(decision, /*new_reservation_ok=*/true);
  EXPECT_FALSE(commit.release_old_locks);
  EXPECT_FALSE(commit.republish_path);
}

TEST(DeadlockRerouteTest, NoBlockedEdgeMeansNoReroute) {
  const StationCatalog catalog = MakeCatalog();
  const auto decision = PlanDeadlockReroute(MakeRequest(catalog, {}));
  EXPECT_EQ(decision.kind, RerouteDecision::Kind::kNoReroute);
  EXPECT_EQ(decision.reason, "no blocked edge in deadlock cycle");
}

TEST(DeadlockRerouteTest, CatalogNotLoadedMeansNoReroute) {
  const StationCatalog catalog = MakeCatalog();
  auto request = MakeRequest(catalog, {"route_edge:dropoff_B__pickup_A"});
  request.catalog_loaded = false;
  EXPECT_EQ(PlanDeadlockReroute(request).kind, RerouteDecision::Kind::kNoReroute);
  request.catalog_loaded = true;
  request.catalog = nullptr;
  EXPECT_EQ(PlanDeadlockReroute(request).kind, RerouteDecision::Kind::kNoReroute);
}

TEST(DeadlockRerouteTest, AttemptsExhausted) {
  const StationCatalog catalog = MakeCatalog();
  auto request = MakeRequest(catalog, {"route_edge:dropoff_B__pickup_A"});
  request.attempt = 1;
  request.max_attempts = 1;
  const auto decision = PlanDeadlockReroute(request);
  EXPECT_EQ(decision.kind, RerouteDecision::Kind::kExhausted);
  EXPECT_TRUE(decision.new_path.empty());
}

// 替代路线与当前一致（受阻边不在当前路径上，例如车已驶过该边）：
// 不算真的绕行，必须报 kNoAlternative 而不是"重发同一条路"。
TEST(DeadlockRerouteTest, IdenticalPathIsNotAReroute) {
  const StationCatalog catalog = MakeCatalog();
  auto request = MakeRequest(catalog, {"route_edge:somewhere_else__x"});
  request.current_path = {"pickup_A", "dropoff_B"};  // 直连仍是最短路
  const auto decision = PlanDeadlockReroute(request);
  EXPECT_EQ(decision.kind, RerouteDecision::Kind::kNoAlternative);
  EXPECT_EQ(decision.reason, "alternative route identical to current path");
}

TEST(DeadlockRerouteTest, MissingStationsMeansNoReroute) {
  const StationCatalog catalog = MakeCatalog();
  auto request = MakeRequest(catalog, {"route_edge:dropoff_B__pickup_A"});
  request.pickup_station.clear();
  EXPECT_EQ(PlanDeadlockReroute(request).kind, RerouteDecision::Kind::kNoReroute);
}

