TEST(DeadlockRerouteTest, NoAlternativeReportsReason) {
  const StationCatalog catalog = MakeCatalog();
  const auto decision = PlanDeadlockReroute(MakeRequest(
      catalog, {"route_edge:dropoff_B__pickup_A", "route_edge:n1__pickup_A",
                "route_edge:dropoff_B__n1"}));
  EXPECT_EQ(decision.kind, RerouteDecision::Kind::kNoAlternative);
  EXPECT_TRUE(decision.new_path.empty());
  EXPECT_TRUE(decision.new_route_locks.empty());
  EXPECT_EQ(decision.reason, "no alternative route avoiding blocked edges");
}

// 场景 3（关键）：新路预约失败时，两个落地动作都必须为 false ——
// 保持旧锁、不重发路线。
TEST(DeadlockRerouteTest, ReservationFailureKeepsOriginalLocks) {
  const StationCatalog catalog = MakeCatalog();
  const auto decision = PlanDeadlockReroute(
      MakeRequest(catalog, {"route_edge:dropoff_B__pickup_A"}));
  ASSERT_EQ(decision.kind, RerouteDecision::Kind::kRerouteReady);

  const auto failed = PlanDeadlockRerouteCommit(decision, /*new_reservation_ok=*/false);
  EXPECT_FALSE(failed.release_old_locks);
  EXPECT_FALSE(failed.republish_path);
  EXPECT_FALSE(failed.reason.empty());

  const auto committed = PlanDeadlockRerouteCommit(decision, /*new_reservation_ok=*/true);
  EXPECT_TRUE(committed.release_old_locks);
  EXPECT_TRUE(committed.republish_path);
}

TEST(DeadlockRerouteTest, CommitWithoutRerouteDoesNothing) {
  RerouteDecision decision;  // kNoReroute
  const auto commit = PlanDeadlockRerouteCommit(decision, /*new_reservation_ok=*/true);
  EXPECT_FALSE(commit.release_old_locks);
  EXPECT_FALSE(commit.republish_path);
}

TEST(DeadlockRerouteTest, NoBlockedEdgeMeansNoReroute) {
  const StationCatalog catalog = MakeCatalog();
  const auto decision = PlanDeadlockReroute(MakeRequest(catalog, {}));
  EXPECT_EQ(decision.kind, RerouteDecision::Kind::kNoReroute);
  EXPECT_EQ(decision.reason, "no blocked edge in deadlock cycle");
}

TEST(DeadlockRerouteTest, CatalogNotLoadedMeansNoReroute) {
  const StationCatalog catalog = MakeCatalog();
  auto request = MakeRequest(catalog, {"route_edge:dropoff_B__pickup_A"});
  request.catalog_loaded = false;
  EXPECT_EQ(PlanDeadlockReroute(request).kind, RerouteDecision::Kind::kNoReroute);
  request.catalog_loaded = true;
  request.catalog = nullptr;
  EXPECT_EQ(PlanDeadlockReroute(request).kind, RerouteDecision::Kind::kNoReroute);
}

TEST(DeadlockRerouteTest, AttemptsExhausted) {
  const StationCatalog catalog = MakeCatalog();
  auto request = MakeRequest(catalog, {"route_edge:dropoff_B__pickup_A"});
  request.attempt = 1;
  request.max_attempts = 1;
  const auto decision = PlanDeadlockReroute(request);
  EXPECT_EQ(decision.kind, RerouteDecision::Kind::kExhausted);
  EXPECT_TRUE(decision.new_path.empty());
}

// 替代路线与当前一致（受阻边不在当前路径上，例如车已驶过该边）：
// 不算真的绕行，必须报 kNoAlternative 而不是"重发同一条路"。
TEST(DeadlockRerouteTest, IdenticalPathIsNotAReroute) {
  const StationCatalog catalog = MakeCatalog();
  auto request = MakeRequest(catalog, {"route_edge:somewhere_else__x"});
  request.current_path = {"pickup_A", "dropoff_B"};  // 直连仍是最短路
  const auto decision = PlanDeadlockReroute(request);
  EXPECT_EQ(decision.kind, RerouteDecision::Kind::kNoAlternative);
  EXPECT_EQ(decision.reason, "alternative route identical to current path");
}

TEST(DeadlockRerouteTest, MissingStationsMeansNoReroute) {
  const StationCatalog catalog = MakeCatalog();
  auto request = MakeRequest(catalog, {"route_edge:dropoff_B__pickup_A"});
  request.pickup_station.clear();
  EXPECT_EQ(PlanDeadlockReroute(request).kind, RerouteDecision::Kind::kNoReroute);
}

