        continue;
      }

      // 1) 先按新路径预留（全有或全无）。**这一步失败就什么都不动**：
      //    不释放旧锁、不重发路线——否则两单会同时落在旧路线上。
      bool reservation_ok = false;
      std::string reservation_message;
      if (UseTimeSpaceMode()) {
        std::vector<std::string> nodes;
        if (catalog_reloader_ != nullptr && catalog_reloader_->loaded() &&
            !active_it->second.pickup_station.empty()) {
          const auto route_path = amr_dispatcher_core::catalog::FindRoutePath(
              catalog_reloader_->catalog(), active_it->second.pickup_station,
              active_it->second.dropoff_station);
          if (route_path.has_value()) {
            nodes = *route_path;
          }
        }
        reservation_ok = ReserveTimeSpaceForMission(mission_id, nodes, &reservation_message);
      } else {
        const auto reserve =
            reservation_table_->Reserve(mission_id, decision.new_route_locks);
        reservation_ok = reserve.success;
        reservation_message = reserve.message;
      }

      // 2) 只有预约成功才允许释放旧锁并重发路线（顺序由纯函数裁决）
      const auto commit = amr_dispatcher_core::workflow::PlanDeadlockRerouteCommit(
          decision, reservation_ok);
      if (!commit.republish_path) {
        RCLCPP_WARN(get_logger(), "Reroute for mission %s not committed: %s (%s)",
                    mission_id.c_str(), commit.reason.c_str(),
                    reservation_message.c_str());
        continue;
      }

      // 旧路线上**不在新路径里**的静态锁逐条释放（新路已握在手里，不会出现空窗）
      std::vector<std::string> stale_locks;
      const std::unordered_set<std::string> new_locks(decision.new_route_locks.begin(),
                                                      decision.new_route_locks.end());
      for (const auto& lock_id : path_it->second.empty()
                                     ? std::vector<std::string>{}
                                     : amr_dispatcher_core::dispatcher::ResourceTable::
                                           BuildLockIds(path_it->second, true)) {
        if (new_locks.count(lock_id) == 0) {
          stale_locks.push_back(lock_id);
        }
      }
      const auto released =
          reservation_table_->ReleaseResources(mission_id, stale_locks);
      if (UseTimeSpaceMode() && !released.empty()) {
        ReleaseTimeSpaceForResources(mission_id, released);
      }

      // 3) 更新存档路径与等待记录，重发路径（local_sim 发 /plan，VDA 发新 order）
      mission_route_paths_[mission_id] = decision.new_path;
      mission_reserved_at_[mission_id] = now_ts;
      pending_wait_.erase(mission_id);
      if (IsManagedVda5050Vehicle(active_it->second.assigned_vehicle_id)) {
        PublishVda5050Order(mission_id, active_it->second.assigned_vehicle_id);
      }
      PublishReroutePlan(mission_id, decision.new_path);

      // 4) 记账与可观测
      mission_reroute_attempts_[mission_id]++;
      mission_last_progress_[mission_id] = now_ts;
      RCLCPP_INFO(get_logger(),
                  "Deadlock reroute: mission %s now on %zu node(s) avoiding %zu blocked edge(s), "
                  "released %zu old lock(s)",
                  mission_id.c_str(), decision.new_path.size(), blocked.size(),
                  released.size());
      if (event_log_) {
        amr_dispatcher_core::dispatcher::MissionEvent evt;
        evt.stamp = "now";
        evt.mission_id = mission_id;
        evt.event = "rerouted";
        evt.message = "blocked edges avoided=" + std::to_string(blocked.size()) +
                      ", new path node(s)=" + std::to_string(decision.new_path.size());
        event_log_->Append(evt);
      }
      rerouted.insert(mission_id);
    }
  }
  return rerouted;
}

void DispatcherNode::PublishReroutePlan(const std::string& mission_id,
                                       const std::vector<std::string>& path_node_ids) {
  if (path_node_ids.empty() || catalog_reloader_ == nullptr || !catalog_reloader_->loaded()) {
    return;
  }
  const auto& catalog = catalog_reloader_->catalog();
  const auto* first = amr_dispatcher_core::catalog::FindStation(catalog, path_node_ids.front());
  const auto* last = amr_dispatcher_core::catalog::FindStation(catalog, path_node_ids.back());
  if (last == nullptr) {
    return;  // 终点不可解析：保持既有路径，不发布半截折线
  }
  amr_dispatcher_core::Pose2D start;
  if (first != nullptr) {
    start = {first->x, first->y, first->yaw};
  } else {
    const auto active_it = active_missions_.find(mission_id);
    (void)active_it;
    start = {current_pose_.x, current_pose_.y, current_pose_.yaw};
  }
  const amr_dispatcher_core::Pose2D goal{last->x, last->y, last->yaw};
  const auto waypoints = planner_ ? planner_->Plan(start, goal)
                                  : std::vector<amr_dispatcher_core::Pose2D>{};
  if (waypoints.empty()) {
    RCLCPP_WARN(get_logger(), "Reroute for mission %s: planner returned empty path",
                mission_id.c_str());
    return;
  }
  nav_msgs::msg::Path path_msg;
  path_msg.header.stamp = now();
  path_msg.header.frame_id = "map";
  path_msg.poses.reserve(waypoints.size());
  for (const auto& wp : waypoints) {
    geometry_msgs::msg::PoseStamped ps;
    ps.header = path_msg.header;
    ps.pose.position.x = wp.x;
    ps.pose.position.y = wp.y;
    ps.pose.orientation.z = std::sin(wp.theta / 2.0);
    ps.pose.orientation.w = std::cos(wp.theta / 2.0);
    path_msg.poses.push_back(ps);
  }
  const auto active_it = active_missions_.find(mission_id);
  const std::string vehicle_id =
      active_it != active_missions_.end() ? active_it->second.assigned_vehicle_id : std::string();
  // VDA 5050 车自带控制器：不发本地 /plan（与派发路径同一约束）
  if (!IsManagedVda5050Vehicle(vehicle_id)) {
    PublishPlanForVehicle(vehicle_id, path_msg);
  }
}

