  if (line.empty() || line.front() == '#') {
    continue;
  }

  if (line == "stations:" || line == "edges:" || line == "routes:" || line == "road_nodes:" ||
      line == "version:") {
    flush_station();
    flush_road_node();
    flush_edge();
    section = line.substr(0, line.size() - 1);
    continue;
