#include "amr_dispatcher_core/workflow/auto_charging_planning.hpp"

#include <gtest/gtest.h>

using amr_dispatcher_core::workflow::AutoChargingDecision;
using amr_dispatcher_core::workflow::AutoChargingRequest;
using amr_dispatcher_core::workflow::PlanAutoCharging;

namespace {

// 一辆"可以插单"的车：在线、空闲、未隔离、电量低于机会阈值、充电站已知。
AutoChargingRequest MakeEligible(double battery_percent = 20.0) {
  AutoChargingRequest request;
  request.enabled = true;
  request.vehicle_id = "amr_01";
  request.battery_percent = battery_percent;
  request.charger_station_id = "station_charge_1";
  request.charger_station_known = true;
  return request;
}

}  // namespace

TEST(AutoChargingPlanningTest, DisabledByDefault) {
  AutoChargingRequest request;  // enabled=false
  EXPECT_EQ(PlanAutoCharging(request).kind, AutoChargingDecision::Kind::kDisabled);
}

TEST(AutoChargingPlanningTest, HealthyBatteryDoesNotQueue) {
  EXPECT_EQ(PlanAutoCharging(MakeEligible(80.0)).kind,
            AutoChargingDecision::Kind::kBatteryOk);
}

TEST(AutoChargingPlanningTest, LowBatteryQueuesOpportunityCharge) {
  const auto decision = PlanAutoCharging(MakeEligible(25.0));
  ASSERT_EQ(decision.kind, AutoChargingDecision::Kind::kQueueCharge);
  EXPECT_FALSE(decision.critical);
  EXPECT_EQ(decision.priority, 0);  // opportunity_priority
  EXPECT_EQ(decision.charger_station_id, "station_charge_1");
}

TEST(AutoChargingPlanningTest, CriticalBatteryUsesHigherPriority) {
  const auto decision = PlanAutoCharging(MakeEligible(10.0));
  ASSERT_EQ(decision.kind, AutoChargingDecision::Kind::kQueueCharge);
  EXPECT_TRUE(decision.critical);
  EXPECT_EQ(decision.priority, 5);  // critical_priority
}

// 阈值边界：等于机会阈值即插单（电量只会继续降），等于临界阈值算临界。
TEST(AutoChargingPlanningTest, ThresholdBoundariesAreInclusive) {
  EXPECT_EQ(PlanAutoCharging(MakeEligible(30.0)).kind,
            AutoChargingDecision::Kind::kQueueCharge);
  EXPECT_TRUE(PlanAutoCharging(MakeEligible(15.0)).critical);
  EXPECT_FALSE(PlanAutoCharging(MakeEligible(15.01)).critical);
}

// 去重是这套逻辑最容易漏的一条：没有它，每 tick 都会再插一条充电单。
TEST(AutoChargingPlanningTest, ExistingChargeMissionIsNotDuplicated) {
  auto request = MakeEligible(5.0);
  request.has_pending_charge_mission = true;
  EXPECT_EQ(PlanAutoCharging(request).kind,
            AutoChargingDecision::Kind::kAlreadyQueued);
}

// 去重先于可用性判定：车忙但已经有充电单时，报"已有充电单"而不是"车忙"，
// 否则运维会以为系统没在管这辆车。
TEST(AutoChargingPlanningTest, DedupBeatsAvailabilityReason) {
  auto request = MakeEligible(5.0);
  request.has_pending_charge_mission = true;
  request.busy = true;
  EXPECT_EQ(PlanAutoCharging(request).kind,
            AutoChargingDecision::Kind::kAlreadyQueued);
}

TEST(AutoChargingPlanningTest, BusyVehicleIsSkipped) {
  auto request = MakeEligible();
  request.busy = true;
  const auto decision = PlanAutoCharging(request);
  EXPECT_EQ(decision.kind, AutoChargingDecision::Kind::kVehicleUnavailable);
  EXPECT_NE(decision.reason.find("busy"), std::string::npos);
}

TEST(AutoChargingPlanningTest, OfflineAndQuarantinedVehiclesAreSkipped) {
  auto offline = MakeEligible();
  offline.online = false;
  EXPECT_EQ(PlanAutoCharging(offline).kind,
            AutoChargingDecision::Kind::kVehicleUnavailable);

  auto quarantined = MakeEligible();
  quarantined.quarantined = true;
  const auto decision = PlanAutoCharging(quarantined);
  EXPECT_EQ(decision.kind, AutoChargingDecision::Kind::kVehicleUnavailable);
  EXPECT_NE(decision.reason.find("quarantined"), std::string::npos);
}

// 电量未知（例如 VDA 5050 车还没上报过 state）：不插单，也不当成 0%。
TEST(AutoChargingPlanningTest, UnknownBatteryIsNotTreatedAsEmpty) {
  auto request = MakeEligible(0.0);
  request.battery_known = false;
  EXPECT_EQ(PlanAutoCharging(request).kind,
            AutoChargingDecision::Kind::kBatteryUnknown);
}

TEST(AutoChargingPlanningTest, MissingChargerStationIsNotGuessed) {
  auto request = MakeEligible();
  request.charger_station_known = false;
  EXPECT_EQ(PlanAutoCharging(request).kind,
            AutoChargingDecision::Kind::kChargerUnknown);

  auto empty_id = MakeEligible();
  empty_id.charger_station_id.clear();
  EXPECT_EQ(PlanAutoCharging(empty_id).kind,
            AutoChargingDecision::Kind::kChargerUnknown);
}

TEST(AutoChargingPlanningTest, CustomThresholdsAndPriorities) {
  auto request = MakeEligible(45.0);
  request.opportunity_threshold_percent = 50.0;
  request.critical_threshold_percent = 20.0;
  request.opportunity_priority = 3;
  request.critical_priority = 9;
  const auto decision = PlanAutoCharging(request);
  ASSERT_EQ(decision.kind, AutoChargingDecision::Kind::kQueueCharge);
  EXPECT_FALSE(decision.critical);
  EXPECT_EQ(decision.priority, 3);
}

#include "amr_dispatcher_core/workflow/auto_charging_planning.hpp"

#include <string>

namespace amr_dispatcher_core::workflow {

AutoChargingDecision PlanAutoCharging(const AutoChargingRequest& request) {
  AutoChargingDecision decision;
  decision.charger_station_id = request.charger_station_id;

  if (!request.enabled) {
    decision.kind = AutoChargingDecision::Kind::kDisabled;
    decision.reason = "auto charging disabled";
    return decision;
  }
  if (!request.battery_known) {
    // 没有电量就不猜：宁可让车继续跑任务，也不凭一次缺失的报文把它叫回充电站
    decision.kind = AutoChargingDecision::Kind::kBatteryUnknown;
    decision.reason = "battery level unknown for vehicle '" + request.vehicle_id + "'";
    return decision;
  }
  if (request.battery_percent > request.opportunity_threshold_percent) {
    decision.kind = AutoChargingDecision::Kind::kBatteryOk;
    decision.reason = "battery above opportunity threshold";
    return decision;
  }
  if (request.has_pending_charge_mission) {
    // 去重：没有这一条，每个 tick 都会给同一台车再插一条充电单
    decision.kind = AutoChargingDecision::Kind::kAlreadyQueued;
    decision.reason = "vehicle '" + request.vehicle_id + "' already has a charge mission";
    return decision;
  }
  if (request.quarantined) {
    decision.kind = AutoChargingDecision::Kind::kVehicleUnavailable;
    decision.reason = "vehicle '" + request.vehicle_id + "' is quarantined";
    return decision;
  }
  if (!request.online) {
    decision.kind = AutoChargingDecision::Kind::kVehicleUnavailable;
    decision.reason = "vehicle '" + request.vehicle_id + "' is offline";
    return decision;
  }
  if (request.busy) {
    decision.kind = AutoChargingDecision::Kind::kVehicleUnavailable;
    decision.reason = "vehicle '" + request.vehicle_id + "' is busy";
    return decision;
  }
  if (!request.charger_station_known || request.charger_station_id.empty()) {
    decision.kind = AutoChargingDecision::Kind::kChargerUnknown;
    decision.reason = "charger station not resolved";
    return decision;
  }

  decision.kind = AutoChargingDecision::Kind::kQueueCharge;
  decision.critical = request.battery_percent <= request.critical_threshold_percent;
  decision.priority = decision.critical ? request.critical_priority : request.opportunity_priority;
  decision.reason = decision.critical ? "critical battery" : "opportunity charging";
  return decision;
}

}  // namespace amr_dispatcher_core::workflow

// 充电任务自动编排（纯函数）。
//
// 现状：core 里已有 `PlanOpportunityCharging`（按**电压**判定），但它只被单测
// 调用，调度器从不使用；调度器能看到的电量是**百分比**（VehicleRuntimeState /
// VDA 5050 batteryCharge），而且"该不该给这台车插一条充电单"还要看：车是否
// 空闲、在线、未隔离、是否已经有一张在跑/在排的充电单、充电站是否存在。
//
// 这里把这套判定独立成纯函数，供每个 tick 对每台车调用一次：
//   * 关闭（默认）-> 什么都不做
//   * 电量高于机会阈值 -> 不插单
//   * 该车已有充电单（排队或在途）-> 不重复插单（否则每 tick 插一条）
//   * 车忙 / 离线 / 隔离 -> 不插单（充电也要占执行槽位，车忙时插单只会堆积）
//   * 充电站未知 -> 不插单（不猜站点）
//   * 否则 -> 插一条 charge 单，临界电量用更高优先级
//
// 铁律：本函数**只产决策**，不碰队列、不碰日志。插单与去重记账由 ROS 侧落地。
#pragma once

#include <string>

namespace amr_dispatcher_core::workflow {

struct AutoChargingRequest {
  bool enabled = false;
  std::string vehicle_id;

  // 车辆运行时状态
  bool online = true;
  bool busy = false;
  bool quarantined = false;
  double battery_percent = 100.0;
  bool battery_known = true;

  // 该车当前是否已有充电单（排队或在途）—— 去重键是"车"，不是"站点"
  bool has_pending_charge_mission = false;

  // 充电目标站（由调用方解析后传入）
  std::string charger_station_id;
  bool charger_station_known = false;

  // 阈值与优先级
  double opportunity_threshold_percent = 30.0;
  double critical_threshold_percent = 15.0;
  int opportunity_priority = 0;
  int critical_priority = 5;
};

struct AutoChargingDecision {
  enum class Kind {
    kDisabled,        // 功能关闭
    kBatteryUnknown,  // 没有电量信息：不插单（不猜）
    kBatteryOk,       // 电量高于机会阈值
    kAlreadyQueued,   // 该车已有充电单
    kVehicleUnavailable,  // 忙 / 离线 / 隔离
    kChargerUnknown,  // 充电站未解析
    kQueueCharge,     // 插单
  };
  Kind kind = Kind::kDisabled;
  bool critical = false;
  int priority = 0;
  std::string charger_station_id;
  std::string reason;
};

AutoChargingDecision PlanAutoCharging(const AutoChargingRequest& request);

}  // namespace amr_dispatcher_core::workflow

#include "amr_dispatcher_core/fleet/vehicle_selection_strategy.hpp"

#include <gtest/gtest.h>

using amr_dispatcher_core::fleet::kSelectionBatteryPenaltyWeight;
using amr_dispatcher_core::fleet::kSelectionBatteryReferencePercent;
using amr_dispatcher_core::fleet::ParseVehicleSelectionStrategy;
using amr_dispatcher_core::fleet::RankVehiclesForSelection;
using amr_dispatcher_core::fleet::VehicleRankEntry;
using amr_dispatcher_core::fleet::VehicleSelectionStrategy;
using amr_dispatcher_core::fleet::VehicleSelectionStrategyLabel;

constexpr auto kNearest = VehicleSelectionStrategy::kNearest;
constexpr auto kBatteryPreferred = VehicleSelectionStrategy::kBatteryPreferred;

namespace {

std::vector<VehicleRankEntry> TwoVehicles(double near_battery, double far_battery) {
  return {VehicleRankEntry{"near", 0.0, near_battery},
          VehicleRankEntry{"far", 0.0, far_battery}};
}

}  // namespace

TEST(VehicleSelectionStrategyTest, ParseAndLabelRoundTrip) {
  VehicleSelectionStrategy parsed = kNearest;
  EXPECT_TRUE(ParseVehicleSelectionStrategy("nearest", &parsed));
  EXPECT_EQ(parsed, kNearest);
  EXPECT_TRUE(ParseVehicleSelectionStrategy("battery_preferred", &parsed));
  EXPECT_EQ(parsed, kBatteryPreferred);
  EXPECT_STREQ(VehicleSelectionStrategyLabel(kNearest), "nearest");
  EXPECT_STREQ(VehicleSelectionStrategyLabel(kBatteryPreferred), "battery_preferred");
}

// 未知标签绝不猜测：调用方据此回落到默认策略并告警。
TEST(VehicleSelectionStrategyTest, UnknownLabelIsRejected) {
  VehicleSelectionStrategy parsed = kBatteryPreferred;
  EXPECT_FALSE(ParseVehicleSelectionStrategy("auction", &parsed));
  EXPECT_FALSE(ParseVehicleSelectionStrategy("", &parsed));
  EXPECT_FALSE(ParseVehicleSelectionStrategy("Nearest", &parsed));  // 大小写敏感
  EXPECT_EQ(parsed, kBatteryPreferred);  // 未被改写
  EXPECT_FALSE(ParseVehicleSelectionStrategy("nearest", nullptr));
}

TEST(VehicleSelectionStrategyTest, NearestPicksLowestCost) {
  const std::vector<VehicleRankEntry> vehicles{{"b", 0.0, 90.0}, {"a", 0.0, 10.0}};
  const std::unordered_map<std::string, double> costs{{"a", 5.0}, {"b", 2.0}};
  const auto ranked = RankVehiclesForSelection(kNearest, vehicles, costs);
  ASSERT_EQ(ranked.size(), 2u);
  EXPECT_EQ(ranked[0].vehicle_id, "b");
  EXPECT_DOUBLE_EQ(ranked[0].score, 2.0);
}

// nearest 策略**不看电量**：这是改动前的行为，必须逐字保持。
TEST(VehicleSelectionStrategyTest, NearestIgnoresBattery) {
  const auto ranked = RankVehiclesForSelection(
      kNearest, TwoVehicles(/*near_battery=*/5.0, /*far_battery=*/100.0),
      {{"near", 3.0}, {"far", 10.0}});
  EXPECT_EQ(ranked[0].vehicle_id, "near");
}

// 距离接近时，低电量软惩罚足以把顺序翻转过去。
TEST(VehicleSelectionStrategyTest, BatteryPreferredFlipsCloseRace) {
  // near: 3.0m @ 10%  -> penalty = (50-10)/100*0.25 = 0.10 -> 3.30
  // far:  3.2m @ 95%  -> 不打折                              -> 3.20
  const auto ranked = RankVehiclesForSelection(
      kBatteryPreferred, TwoVehicles(/*near_battery=*/10.0, /*far_battery=*/95.0),
      {{"near", 3.0}, {"far", 3.2}});
  ASSERT_EQ(ranked.size(), 2u);
  EXPECT_EQ(ranked[0].vehicle_id, "far");
  EXPECT_DOUBLE_EQ(ranked[0].score, 3.2);
  EXPECT_NEAR(ranked[1].score, 3.30, 1e-9);
}

// 惩罚有上限：明显更近的车不能输给远处满电车（不为了省电牺牲吞吐）。
TEST(VehicleSelectionStrategyTest, BatteryPreferredPenaltyIsBounded) {
  const auto ranked = RankVehiclesForSelection(
      kBatteryPreferred, TwoVehicles(/*near_battery=*/1.0, /*far_battery=*/100.0),
      {{"near", 3.0}, {"far", 100.0}});
  EXPECT_EQ(ranked[0].vehicle_id, "near");
  // 上界：3.0 * (1 + 0.5*0.25) = 3.375，仍远小于 100
  const double worst = 3.0 * (1.0 + (kSelectionBatteryReferencePercent - 1.0) / 100.0 *
                                       kSelectionBatteryPenaltyWeight);
  EXPECT_NEAR(ranked[0].score, worst, 1e-9);
  EXPECT_LT(ranked[0].score, 4.0);
}

// 参考电量之上不再加分：满电车之间只比距离（避免"电量 99 胜过 95"这种噪声）。
TEST(VehicleSelectionStrategyTest, AboveReferenceBatteryGetsNoBonus) {
  const std::vector<VehicleRankEntry> vehicles{{"hi", 0.0, 100.0}, {"lo", 0.0, 60.0}};
  const auto ranked = RankVehiclesForSelection(kBatteryPreferred, vehicles,
                                               {{"hi", 5.0}, {"lo", 4.0}});
  EXPECT_EQ(ranked[0].vehicle_id, "lo");  // 距离优先，两者都不打折
  EXPECT_DOUBLE_EQ(ranked[0].score, 4.0);
  EXPECT_DOUBLE_EQ(ranked[1].score, 5.0);
}

// 同分必须由 id 决定，否则容器遍历序会让每次结果不同。
TEST(VehicleSelectionStrategyTest, TiesBreakOnVehicleId) {
  const std::vector<VehicleRankEntry> vehicles{{"zeta", 0.0, 90.0}, {"alpha", 0.0, 90.0},
                                               {"mid", 0.0, 90.0}};
  const auto ranked = RankVehiclesForSelection(
      kNearest, vehicles, {{"zeta", 4.0}, {"alpha", 4.0}, {"mid", 4.0}});
  ASSERT_EQ(ranked.size(), 3u);
  EXPECT_EQ(ranked[0].vehicle_id, "alpha");
  EXPECT_EQ(ranked[1].vehicle_id, "mid");
  EXPECT_EQ(ranked[2].vehicle_id, "zeta");
}

// 成本缺失的候选不参与排序（调用方据此判定"无路可达"）。
TEST(VehicleSelectionStrategyTest, MissingCostIsDropped) {
  const std::vector<VehicleRankEntry> vehicles{{"a", 0.0, 50.0}, {"b", 0.0, 50.0}};
  const auto ranked = RankVehiclesForSelection(kBatteryPreferred, vehicles, {{"a", 1.0}});
  ASSERT_EQ(ranked.size(), 1u);
  EXPECT_EQ(ranked[0].vehicle_id, "a");
}

TEST(VehicleSelectionStrategyTest, EmptyInputYieldsEmptyRanking) {
  EXPECT_TRUE(RankVehiclesForSelection(kBatteryPreferred, {}, {}).empty());
}

TEST(VehicleSelectionStrategyTest, AllCostsMissingYieldsEmptyRanking) {
  const std::vector<VehicleRankEntry> vehicles{{"a", 0.0, 50.0}};
  EXPECT_TRUE(RankVehiclesForSelection(kNearest, vehicles, {}).empty());
}

#include "amr_dispatcher_core/fleet/vehicle_selection_strategy.hpp"

#include <algorithm>
#include <cmath>

namespace amr_dispatcher_core::fleet {

bool ParseVehicleSelectionStrategy(const std::string& label,
                                   VehicleSelectionStrategy* out) {
  if (out == nullptr) {
    return false;
  }
  if (label == "nearest") {
    *out = VehicleSelectionStrategy::kNearest;
    return true;
  }
  if (label == "battery_preferred") {
    *out = VehicleSelectionStrategy::kBatteryPreferred;
    return true;
  }
  return false;  // 未知标签不猜
}

const char* VehicleSelectionStrategyLabel(VehicleSelectionStrategy strategy) {
  switch (strategy) {
    case VehicleSelectionStrategy::kNearest:
      return "nearest";
    case VehicleSelectionStrategy::kBatteryPreferred:
      return "battery_preferred";
  }
  return "nearest";
}

std::vector<ScoredVehicle> RankVehiclesForSelection(
    VehicleSelectionStrategy strategy, const std::vector<VehicleRankEntry>& eligible,
    const std::unordered_map<std::string, double>& distance_to_pickup_m) {
  std::vector<ScoredVehicle> scored;
  scored.reserve(eligible.size());
  for (const auto& entry : eligible) {
    const auto cost_it = distance_to_pickup_m.find(entry.vehicle_id);
    if (cost_it == distance_to_pickup_m.end()) {
      continue;  // 距离不可算：不参与排序（不盲派）
    }
    ScoredVehicle item;
    item.vehicle_id = entry.vehicle_id;
    item.cost_m = cost_it->second;
    item.battery_percent = entry.battery_percent;
    if (strategy == VehicleSelectionStrategy::kBatteryPreferred &&
        entry.battery_percent < kSelectionBatteryReferencePercent) {
      const double shortfall = kSelectionBatteryReferencePercent - entry.battery_percent;
      const double penalty = (shortfall / 100.0) * kSelectionBatteryPenaltyWeight;
      item.score = item.cost_m * (1.0 + penalty);
    } else {
      item.score = item.cost_m;
    }
    scored.push_back(std::move(item));
  }
  // 全序：分数升序，同分按 vehicle_id 字典序（否则容器遍历序会让结果漂）
  std::stable_sort(scored.begin(), scored.end(),
                   [](const ScoredVehicle& a, const ScoredVehicle& b) {
                     if (std::fabs(a.score - b.score) > 1e-9) {
                       return a.score < b.score;
                     }
                     if (a.cost_m != b.cost_m) {
                       return a.cost_m < b.cost_m;
                     }
                     return a.vehicle_id < b.vehicle_id;
                   });
  return scored;
}

}  // namespace amr_dispatcher_core::fleet

