10	
11	std::string Trim(const std::string& value) {
12	  std::size_t begin = 0;
13	  while (begin < value.size() &&
14	         std::isspace(static_cast<unsigned char>(value[begin])) != 0) {
15	    ++begin;
16	  }
17	  std::size_t end = value.size();
18	  while (end > begin && std::isspace(static_cast<unsigned char>(value[end - 1])) != 0) {
19	    --end;
20	  }
21	  return value.substr(begin, end - begin);
22	}
23	
24	std::string NormalizeKey(const std::string& value) {
25	  std::string key = Trim(value);
26	  std::transform(key.begin(), key.end(), key.begin(), [](unsigned char ch) {
27	    return static_cast<char>(std::tolower(ch));
28	  });
29	  return key;
30	}
31	
32	std::vector<std::string> SplitCommaList(const std::string& value) {
33	  std::vector<std::string> parts;
34	  std::string current;
35	  bool in_quote = false;
36	  for (std::size_t index = 0; index < value.size(); ++index) {
37	    const char ch = value[index];
38	    if (ch == '"' && (index == 0 || value[index - 1] != '\\')) {
39	      in_quote = !in_quote;
40	      current.push_back(ch);
41	      continue;
42	    }
43	    if (ch == ',' && !in_quote) {
44	      parts.push_back(Trim(current));
45	      current.clear();
46	      continue;
47	    }
48	    current.push_back(ch);
49	  }
50	  if (!current.empty() || !value.empty()) {
51	    parts.push_back(Trim(current));
52	  }
53	  return parts;
54	}
55	
56	std::string Unquote(const std::string& value) {
57	  const auto trimmed = Trim(value);
58	  if (trimmed.size() < 2U || trimmed.front() != '"' || trimmed.back() != '"') {
59	    return trimmed;
60	  }
61	  std::string result;
62	  result.reserve(trimmed.size() - 2U);
63	  for (std::size_t index = 1; index + 1U < trimmed.size(); ++index) {
64	    const char ch = trimmed[index];
65	    if (ch != '\\' || index + 2U >= trimmed.size()) {
66	      result.push_back(ch);
67	      continue;
68	    }
69	    const char escaped = trimmed[++index];
70	    switch (escaped) {
71	      case '"':
72	      case '\\':
73	      case '/':
74	        result.push_back(escaped);
75	        break;
76	      case 'n':
77	        result.push_back('\n');
78	        break;
79	      case 'r':
80	        result.push_back('\r');
81	        break;
82	      case 't':
83	        result.push_back('\t');
84	        break;
85	      default:
86	        result.push_back(escaped);
87	        break;
88	    }
89	  }
90	  return result;
91	}
92	
93	class FlatJsonParser {
94	 public:
95	  explicit FlatJsonParser(const std::string& text) : text_(text) {}
96	
97	  std::optional<OrderPayload> Parse(std::string* message) {
98	    OrderPayload payload;
99	    SkipWhitespace();
100	    if (!Consume('{')) {
101	      *message = "payload_json must start with '{'";
102	      return std::nullopt;
103	    }
104	    SkipWhitespace();
105	    if (Consume('}')) {
106	      return payload;
107	    }
108	    while (position_ < text_.size()) {
109	      std::string key;
110	      if (!ParseString(&key, message)) {
111	        return std::nullopt;
112	      }
113	      key = NormalizeKey(key);
114	      SkipWhitespace();
115	      if (!Consume(':')) {
116	        *message = "expected ':' after key '" + key + "'";
117	        return std::nullopt;
118	      }
119	      SkipWhitespace();
120	      if (Peek() == '[') {
121	        std::vector<std::string> values;
122	        if (!ParseArray(&values, message)) {
123	          return std::nullopt;
124	        }
125	        payload.SetList(key, values);
126	      } else {
127	        std::string value;
128	        if (!ParseScalar(&value, message)) {
129	          return std::nullopt;
130	        }
131	        payload.SetString(key, value);
132	      }
133	      SkipWhitespace();
134	      if (Consume('}')) {
135	        SkipWhitespace();
136	        if (position_ != text_.size()) {
137	          *message = "unexpected trailing content after JSON object";
138	          return std::nullopt;
139	        }
140	        return payload;
