  bool required = false;
  std::vector<std::string> allowed_values;  // 若非空，则必须为其中之一
  std::optional<double> min_value;          // 数值下限（适用于 Int/Double）
  std::optional<double> max_value;          // 数值上限（适用于 Int/Double）
};

