1	// Modbus-TCP 纯 C++ 客户端实现（POSIX Socket，零外部三方依赖）。
2	//
3	// 对应 Phase 8 (P0)：
4	// 支持工业标准 Modbus-TCP 报文构建与解析，用于与现场 PLC、自动门控制器与提升机通讯。
5	//
6	// 协议规范：
7	// 1. MBAP 报文头（7 字节）：
8	//    - Transaction ID (2 字节): 事务标识，自增保序
9	//    - Protocol ID    (2 字节): 固定 0x0000 (Modbus)
10	//    - Length         (2 字节): 后续字节数 (Unit ID + PDU)
11	//    - Unit ID        (1 字节): 设备从站地址 (通常为 1 或 255)
12	// 2. 支持功能码 (Function Codes)：
13	//    - 0x01: Read Coils（读线圈/输出状态，如开门中/门已完全开启）
14	//    - 0x02: Read Discrete Inputs（读离散输入，如限位开关）
15	//    - 0x03: Read Holding Registers（读保持寄存器，如电梯当前楼层/故障字）
16	//    - 0x05: Write Single Coil（写单线圈，如触发开门/关门指令）
17	//    - 0x06: Write Single Register（写单寄存器，如设定电梯目标楼层）
18	#pragma once
19	
20	#include <cstdint>
21	#include <string>
22	#include <vector>
23	
24	namespace amr_dispatcher_core::facility {
25	
26	struct ModbusResponse {
27	  bool success = false;
28	  uint8_t function_code = 0;
29	  uint8_t exception_code = 0;
30	  std::vector<bool> coil_values;
31	  std::vector<uint16_t> register_values;
32	  std::string error_message;
33	};
34	
35	// 纯函数报文编解码器（供单元测试和客户端共享，100% 内存单测可覆盖）
36	class ModbusPacketCodec {
37	 public:
38	  static std::vector<uint8_t> BuildReadCoilsRequest(
39	      uint16_t transaction_id, uint8_t unit_id, uint16_t start_addr, uint16_t count);
40	
41	  static std::vector<uint8_t> BuildReadHoldingRegistersRequest(
42	      uint16_t transaction_id, uint8_t unit_id, uint16_t start_addr, uint16_t count);
43	
44	  static std::vector<uint8_t> BuildWriteSingleCoilRequest(
45	      uint16_t transaction_id, uint8_t unit_id, uint16_t coil_addr, bool value);
46	
47	  static std::vector<uint8_t> BuildWriteSingleRegisterRequest(
48	      uint16_t transaction_id, uint8_t unit_id, uint16_t reg_addr, uint16_t value);
49	
50	  static ModbusResponse ParseResponse(
51	      uint16_t expected_tx_id, const uint8_t* data, std::size_t length);
52	};
53	
54	// Modbus-TCP POSIX Socket 客户端
55	class ModbusTcpClient {
56	 public:
57	  ModbusTcpClient(std::string ip, uint16_t port, uint8_t unit_id = 1,
58	                  int timeout_ms = 2000);
59	  ~ModbusTcpClient();
60	
61	  // 禁止拷贝
62	  ModbusTcpClient(const ModbusTcpClient&) = delete;
63	  ModbusTcpClient& operator=(const ModbusTcpClient&) = delete;
64	
65	  bool Connect(std::string* error_msg = nullptr);
66	  void Disconnect();
67	  bool IsConnected() const;
68	
69	  ModbusResponse ReadCoils(uint16_t start_addr, uint16_t count);
70	  ModbusResponse ReadHoldingRegisters(uint16_t start_addr, uint16_t count);
71	  ModbusResponse WriteSingleCoil(uint16_t coil_addr, bool value);
72	  ModbusResponse WriteSingleRegister(uint16_t reg_addr, uint16_t value);
73	
74	 private:
75	  ModbusResponse Transceive(const std::vector<uint8_t>& request, uint16_t tx_id);
76	
77	  std::string ip_;
78	  uint16_t port_;
79	  uint8_t unit_id_;
80	  int timeout_ms_;
81	  int sock_fd_ = -1;
82	  uint16_t next_transaction_id_ = 1;
83	};
84	
85	}  // namespace amr_dispatcher_core::facility
