const int next_time_step = current->time_step + steps;

if (next_time_step > request.max_time_steps) {
  continue;
}

// 边约束检查 (禁止在 current->time_step 经该边移动)
const std::string edge_key1 = current->station_id + "->" + next_station + "@" +
