      state.curr_station = p1.station_id;
      state.next_station = p2.station_id;
      state.is_moving = true;
      return state;
    }
  }

  state.curr_station = path.back().station_id;
  state.next_station = state.curr_station;
  state.is_moving = false;
  return state;
}

