// 规划（逐资源窗口 + 冲突后移）
const auto plan = amr_dispatcher_core::workflow::PlanTimeSpaceReservation(
    candidate, time_space_occupancy_, time_space_timing_);
if (!plan.feasible) {
  if (message != nullptr) *message = plan.reject_reason;
  return false;
}

