    result.all_solved = false;
    result.message = "CBS failed: " + cbs_res.message;
    return result;
  }

  // 4. 将 CBS 规划解回填并转换为 ResourceTimeWindowSet
  result.all_solved = true;
  result.message = "all missions coordinated by CBS";

  for (const auto& req : requests) {

