2682-  if (!deadlock_detector_ || !recovery_policy_) {
2683-    return;
2684-  }
2685-
2686-  // 与 DetectTrafficDeadlockCb 统一锁约定：BuildDeadlockSnapshot 读 active_missions_，
2687-  // 当前虽是单线程 spin（无并发语义变化），但约定不统一迟早会在切
2688-  // MultiThreadedExecutor 时变成数据竞争。
2689-  amr_dispatcher_core::dispatcher::DeadlockSnapshot snap;
2690-  {
2691-    std::lock_guard<std::mutex> lock(active_missions_mutex_);
2692-    snap = BuildDeadlockSnapshot();
2693-  }
2694-
2695-  const auto findings = deadlock_detector_->Detect(snap);
2696-  deadlock_flag_ = !findings.empty();
2697-
2698-  // 拓扑状态投影的死锁输入：存各 finding 的环路径，无死锁时清空
2699-  last_deadlock_findings_.clear();
2700-  for (const auto& finding : findings) {
2701-    if (!finding.cycle_path.empty()) {
2702-      last_deadlock_findings_.push_back(finding.cycle_path);
2703-    }
2704-  }
2705-
2706-  if (deadlock_flag_) {
2707-    RCLCPP_WARN(get_logger(), "Deadlock findings count: %zu", findings.size());
2708-
2709-    // Phase 7 (P1/P2): 优先对有向死锁环尝试执行安全拓扑绕行破环
2710-    bool cycle_resolved_by_reroute = false;
2711-    for (const auto& finding : findings) {
2712-      if (finding.kind == amr_dispatcher_core::dispatcher::DeadlockKind::kMutualBlock &&
2713-          !finding.cycle_path.empty() && catalog_reloader_) {
2714-        amr_dispatcher_core::workflow::DeadlockRecoveryRequest recovery_req;
2715-        recovery_req.catalog = &catalog_reloader_->catalog();
2716-        recovery_req.cycle_mission_ids = finding.mission_ids;
2717-
2718-        // 提取死锁环中涉及的边锁 (奇数位资源为锁名)
2719-        for (std::size_t i = 1; i < finding.cycle_path.size(); i += 2) {
2720-          if (finding.cycle_path[i].rfind("route_edge:", 0) == 0) {
2721-            recovery_req.cycle_blocked_edges.insert(finding.cycle_path[i]);
2722-          }
2723-        }
2724-
2725-        // 构建各涉案在途任务的候选状态
2726-        for (const auto& mid : finding.mission_ids) {
2727-          auto it = active_missions_.find(mid);
2728-          if (it == active_missions_.end()) {
2729-            continue;
2730-          }
2731-          amr_dispatcher_core::workflow::DeadlockRecoveryCandidate cand;
2732-          cand.mission_id = mid;
2733-          cand.priority = it->second.priority;
2734-          cand.destination_node = it->second.dropoff_station;
2735-
2736-          // 反查当前绑定的车辆与最近停靠的安全节点
2737-          auto track_it = mission_tracking_vehicle_.find(mid);
2738-          if (track_it != mission_tracking_vehicle_.end()) {
2739-            cand.vehicle_id = track_it->second;
2740-          } else {
2741-            auto vda_it = vda5050_mission_vehicle_.find(mid);
2742-            if (vda_it != vda5050_mission_vehicle_.end()) {
2743-              cand.vehicle_id = vda_it->second;
2744-            }
2745-          }
2746-
2747-          auto safe_node_it = vehicle_safe_nodes_.find(cand.vehicle_id);
2748-          if (safe_node_it != vehicle_safe_nodes_.end() && !safe_node_it->second.empty()) {
2749-            cand.current_safe_node = safe_node_it->second;
2750-          } else {
2751-            cand.current_safe_node = it->second.pickup_station;
2752-          }
2753-
2754-          auto path_it = mission_route_paths_.find(mid);
2755-          if (path_it != mission_route_paths_.end()) {
2756-            cand.full_original_path = path_it->second;
2757-          }
2758-          if (reservation_table_) {
2759-            for (const auto& [res_id, owner] : reservation_table_->Snapshot()) {
2760-              if (owner == mid) {
2761-                cand.current_held_locks.push_back(res_id);
2762-              }
2763-            }
2764-          }
2765-          recovery_req.candidates.push_back(std::move(cand));
2766-        }
2767-
2768-        const auto recovery_dec =
2769-            amr_dispatcher_core::workflow::PlanDeadlockRecovery(recovery_req);
2770-
2771-        if (recovery_dec.action ==
2772-            amr_dispatcher_core::workflow::DeadlockRecoveryDecision::Action::kRerouteMission) {
2773-          const auto& reroute = recovery_dec.reroute_decision;
2774-          const std::string& mid = recovery_dec.selected_mission_id;
