2783-            reserve_ok = res.success;
2784-          }
2785-
2786-          if (reserve_ok) {
2787-            // 【两阶段置换步骤 2】预留成功：释放旧路线不再需要的废弃锁
2788-            if (!reroute.obsolete_locks.empty() && reservation_table_) {
2789-              reservation_table_->ReleaseResources(mid, reroute.obsolete_locks);
