function parseAndRenderPgm(bytes) {
  // 解析 P5 二进制 PGM
  let offset = 0;
  function readToken() {
    while (offset < bytes.length && (bytes[offset] === 32 || bytes[offset] === 10 || bytes[offset] === 13 || bytes[offset] === 9)) offset++;
    if (offset >= bytes.length) return "";
    if (bytes[offset] === 35) { // comment #
      while (offset < bytes.length && bytes[offset] !== 10 && bytes[offset] !== 13) offset++;
      return readToken();
    }
    let start = offset;
    while (offset < bytes.length && bytes[offset] !== 32 && bytes[offset] !== 10 && bytes[offset] !== 13 && bytes[offset] !== 9) offset++;
    return String.fromCharCode.apply(null, bytes.subarray(start, offset));
  }

  const magic = readToken();
  if (magic !== 'P5') {
    alert("目前仅支持二进制 PGM (P5) 格式！");
    return;
  }
  mapWidth = parseInt(readToken());
  mapHeight = parseInt(readToken());
  const maxVal = parseInt(readToken());
  offset++; // skip trailing newline

  mapCanvas.width = mapWidth;
  mapCanvas.height = mapHeight;
  const ctx = mapCanvas.getContext('2d');
  const imgData = ctx.createImageData(mapWidth, mapHeight);
  gridData = new Array(mapWidth * mapHeight);

  // PGM 坐标系：左上为 (0,0)，ROS 栅格通常以左下为 (0,0)
  for (let r = 0; r < mapHeight; r++) {
    for (let c = 0; c < mapWidth; c++) {
      const val = bytes[offset + r * mapWidth + c];
      const pxIdx = (r * mapWidth + c) * 4;
      imgData.data[pxIdx] = val;
      imgData.data[pxIdx + 1] = val;
      imgData.data[pxIdx + 2] = val;
      imgData.data[pxIdx + 3] = 255;

      // 转换为 ROS 栅格占用概率 (-1, 0, 100)
      // ROS 占据栅格行号从下到上：ros_row = (mapHeight - 1 - r)
      const rosRow = mapHeight - 1 - r;
      const rosIdx = rosRow * mapWidth + c;
      if (val === 254 || val > 240) gridData[rosIdx] = 0; // free
      else if (val === 0 || val < 50) gridData[rosIdx] = 100; // occupied
      else gridData[rosIdx] = -1; // unknown
    }
  }
  ctx.putImageData(imgData, 0, 0);
  currentMapImage = imgData;
  canvasOverlayText.style.display = 'none';

