void WorkerLoop() {
  while (true) {
    QueuedConn conn;
    {
      std::unique_lock<std::mutex> lock(queue_mutex_);
      queue_cv_.wait(lock, [this] { return stopping_ || !pending_.empty(); });
      if (stopping_ && pending_.empty()) {
        return;
      }
      conn = std::move(pending_.front());
      pending_.pop_front();
    }
    HandleClientSafely(conn);
    close(conn.fd);
  }
}

