void HandleClientSafely(const QueuedConn& conn) {
  try {
    if (conn.head_ok) {
      // accept 线程已经解析好请求头：worker 只续读请求体，不重复读头。
      HttpRequest req = conn.req;
      const ReadStatus body_status =
