608	  // 从本地缓存组装逐组件探针。时间在这里读（纯逻辑层不碰时钟）。
609	  std::vector<ComponentProbe> CollectComponentProbes() {
610	    using namespace std::chrono;
611	    const auto now = steady_clock::now();
612	
613	    std::lock_guard<std::mutex> lock(data_mutex_);
614	    const auto age_of = [&now](const steady_clock::time_point& stamp) -> double {
615	      return duration<double>(now - stamp).count();
616	    };
617	
618	    std::vector<ComponentProbe> probes;
619	
620	    ComponentProbe dispatcher;
621	    dispatcher.name = "dispatcher";
622	    dispatcher.seen = state_seen_;
623	    dispatcher.age_seconds = state_seen_ ? age_of(last_state_arrival_) : -1.0;
624	    dispatcher.stale_after_seconds = readyz_dispatcher_state_stale_sec_;
625	    // 能收到 /dispatcher/state 就说明节点在 active 并且定时器在跑；
626	    // 消息本身不带 lifecycle 状态，所以判据就是"新鲜"。
627	    dispatcher.semantic_ok = true;
628	    dispatcher.detail = "state_age_ms=" +
629	                        std::to_string(static_cast<long long>(dispatcher.age_seconds * 1000.0));
630	    probes.push_back(dispatcher);
631	
632	    ComponentProbe safety;
633	    safety.name = "safety";
634	    safety.seen = safety_seen_;
635	    safety.age_seconds = safety_seen_ ? age_of(last_safety_arrival_) : -1.0;
636	    safety.stale_after_seconds = readyz_safety_stale_sec_;
