                  catalog_reloader_->catalog().stations.size());
      // SkeletonPlanner 持有目录副本：热重载后必须同步，否则仍按旧折线规划
      auto* skeleton_planner =
          dynamic_cast<amr_dispatcher_core::planning::SkeletonPlanner*>(planner_.get());
