184	// 错误响应后先把对端还在发送的数据读掉再关闭。
185	// 直接 close 一个仍有未读数据的连接会发 RST，客户端可能连 400/413 都收不到。
186	// 上限 2 MiB + 单次读超时，恶意客户端最多多占一个读超时。
187	void DrainForClose(int fd, std::size_t max_bytes = 2U * 1024U * 1024U) {
188	  char sink[4096];
189	  std::size_t drained = 0;
190	  while (drained < max_bytes) {
191	    const ssize_t n = ::read(fd, sink, sizeof(sink));
192	    if (n > 0) {
193	      drained += static_cast<std::size_t>(n);
194	      continue;
195	    }
196	    if (n < 0 && errno == EINTR) continue;
197	    return;
198	  }
199	}
