  const bool is_ready =
      (current_dispatcher_state_ == "active") && safety_fresh && safety_healthy_;
  resp->ready = is_ready;
  resp->healthy = safety_fresh && safety_healthy_;

  if (is_ready) {
    resp->state = "READY";
