// ==========================================
// 就绪探针 + 临时拓扑管制
// ==========================================
// 安全约定：服务端返回的字符串一律用 textContent 赋值，绝不拼进 innerHTML。
// （页面上已有的 fetchVehicleLinks 用了 innerHTML 插值，那属于既有代码，
//   新面板不照抄这个扩大风险面的写法。）
const readyzTable = document.getElementById('readyzTable');
const readyzState = document.getElementById('readyzState');
const overlayBadge = document.getElementById('overlayBadge');
const topoResult = document.getElementById('topoResult');
const topoYaml = document.getElementById('topoYaml');
const topoApplyBtn = document.getElementById('topoApplyBtn');
// 预演成功时记录"哪一份文本"通过了，文本一变立即失效客户端防线
let previewedYaml = null;

function topoBase() {
  return baseUrlInput.value.replace(/\/$/, '');
}

function setTopoPill(el, text, cls) {
  el.textContent = text;
  el.className = `pill ${cls}`;
}

function renderTopoResult(status, body) {
  topoResult.textContent = `HTTP ${status}\n` + JSON.stringify(body, null, 2);
}

async function fetchReadiness() {
  const pane = readyzTable;
  try {
    // 503 的 body 同样要渲染：res.ok 只决定颜色，不影响解析
    const res = await fetch(`${topoBase()}/readyz`);
    const data = await res.json();
    setTopoPill(readyzState, data.state || (res.ok ? 'READY' : 'NOT READY'),
                res.ok ? 'green' : 'red');
    const rows = (data.components || []).map(c => {
      const tr = document.createElement('tr');

      const tdName = document.createElement('td');
      const pill = document.createElement('span');
      const okCls = !c.monitored ? 'blue' : (c.ok ? 'green' : 'red');
      const okText = !c.monitored ? '未监控' : (c.ok ? 'OK' : '异常');
      pill.className = `pill ${okCls}`;
      pill.textContent = okText;
      tdName.appendChild(document.createTextNode(`${c.component} `));
      tdName.appendChild(pill);

      const tdReason = document.createElement('td');
      tdReason.textContent = c.reason || '-';

      const tdAge = document.createElement('td');
      const age = typeof c.age_seconds === 'number'
        ? (c.age_seconds < 0 ? '从未收到' : `${c.age_seconds.toFixed(1)}s`)
        : '-';
      tdAge.textContent = `${age} / ${c.stale_after_seconds}s`;

      const tdDetail = document.createElement('td');
      tdDetail.textContent = c.detail || '-';

      tr.append(tdName, tdReason, tdAge, tdDetail);
      return tr;
    });
    pane.replaceChildren(...(rows.length ? rows : [
      Object.assign(document.createElement('tr'), {
        textContent: '无组件数据（网关刚启动？）'
      })
    ]));
  } catch (err) {
    setTopoPill(readyzState, '探针不可达', 'red');
    pane.replaceChildren(Object.assign(document.createElement('tr'), {
      textContent: `读取 /readyz 失败: ${err.message}`
    }));
  }
}

function renderOverlayState(data) {
  document.getElementById('overlayRevision').textContent =
    `${data.revision} (${data.overlay_active ? '生效中' : '未生效'})`;
  document.getElementById('overlayCounts').textContent =
    `${data.blocked_edges} 封路 / ${data.one_way_edges} 单向 / ${data.markers} 临时站点`;
  document.getElementById('overlayBaseHash').textContent =
    data.base_map_hash || '(未记录，将随下次提交写入)';
  setTopoPill(overlayBadge,
              data.overlay_active ? `叠加层生效 rev=${data.revision}` : '无叠加层',
              data.overlay_active ? 'yellow' : 'blue');
  // 从状态预填 expected_map_hash，避免操作员抄错
  const hashInput = document.getElementById('topoBaseHash');
  if (!hashInput.value && data.effective_map_hash) {
    hashInput.value = data.effective_map_hash;
  }
}

async function fetchTopologyOverlay() {
  try {
    const res = await fetch(`${topoBase()}/api/v1/topology/overlay`);
    const data = await res.json();
    renderOverlayState(data);
  } catch (err) {
    setTopoPill(overlayBadge, '叠加层状态不可达', 'red');
  }
}

async function postTopology(path, body) {
  const res = await fetch(`${topoBase()}${path}`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(body)
  });
  let data = {};
  try { data = await res.json(); } catch (e) { data = { error: `HTTP ${res.status}` }; }
  renderTopoResult(res.status, data);
  return { res, data };
}

// 单边管制：必填 operator/reason，服务端独立复验
document.getElementById('topoBlockBtn').addEventListener('click', async () => {
  const from = document.getElementById('topoFrom').value.trim();
  const to = document.getElementById('topoTo').value.trim();
  const action = document.getElementById('topoAction').value;
  const operatorId = document.getElementById('topoOperator').value.trim();
  const reason = document.getElementById('topoReason').value.trim();
  if (!from || !to || !operatorId || !reason) {
    setStatus('拓扑管制需要填写 from/to、操作员 id 与原因', false);
    return;
  }
  if (!window.confirm(
        `确认对 ${from} <-> ${to} 执行 ${action}？\n\n` +
        `• 变更会立即影响新规划；在途车可能需要绕行\n` +
        `• 若该边是唯一通路，提交会被拒绝（不会出现孤岛站点）\n\n` +
        `操作员: ${operatorId}\n原因: ${reason}`)) {
    return;
  }
  const pathMap = {
    block: '/api/v1/topology/block_edge',
    unblock: '/api/v1/topology/unblock_edge',
    one_way: '/api/v1/topology/one_way_edge',
    two_way: '/api/v1/topology/two_way_edge'
  };
  const { data } = await postTopology(pathMap[action] || pathMap.block, {
    from_station: from,
    to_station: to,
    direction: document.getElementById('topoDirection').value,
    operator_id: operatorId,
    reason: reason,
    expected_map_hash: document.getElementById('topoBaseHash').value.trim(),
    allow_edge_under_vehicle: document.getElementById('topoAllowUnderVehicle').checked,
    confirm: true
  });
  if (data.status === 'ok' || data.status === 'noop') {
    setStatus(`✅ 拓扑管制已提交 (revision ${data.overlay_revision})`, true);
  } else {
    setStatus(`拓扑管制被拒绝: ${data.error_code || data.message || data.error}`, false);
  }
  fetchTopologyOverlay();
});

document.getElementById('topoLoadBtn').addEventListener('click', async () => {
  try {
    const res = await fetch(`${topoBase()}/api/v1/topology/overlay?yaml=1`);
    const data = await res.json();
    topoYaml.value = data.overlay_yaml || '';
    previewedYaml = null;
    topoApplyBtn.disabled = true;
    renderTopoResult(res.status, data);
    renderOverlayState(data);
  } catch (err) {
    setStatus(`读取叠加层失败: ${err.message}`, false);
  }
});

document.getElementById('topoPreviewBtn').addEventListener('click', async () => {
  const text = topoYaml.value;
  if (!text.trim()) {
