async function waitStatus(predicate, timeoutMs = 8000) {
  const started = Date.now();
  let last = '';
  while (Date.now() - started < timeoutMs) {
    last = await statusText();
    if (predicate(last)) return last;
    await sleep(200);
  }
  return last;
}

