# 验证内嵌 python 找桥边的逻辑在真实文件上可运行
import re
path='config/generated/stations.yaml'
text=open(path,encoding='utf-8').read().splitlines()
stations=[];road=[];edges=[];sec=None;cur=None
for raw in text:
    s=raw.strip()
    if s in ('stations:','edges:','road_nodes:','version:'):
        sec=s;continue
    m=re.match(r'- id: "?([^"\s]+)"?',s)
    if m and sec in ('stations:','road_nodes:'):
        (stations if sec=='stations:' else road).append(m.group(1));continue
    m=re.match(r'- from: "?([^"\s]+)"?',s)
    if m and sec=='edges:':
        cur=m.group(1);continue
    m=re.match(r'to: "?([^"\s]+)"?',s)
    if m and sec=='edges:' and cur is not None:
        edges.append((cur,m.group(1)));cur=None
adj={}
for a,b in edges:
    adj.setdefault(a,set()).add(b);adj.setdefault(b,set()).add(a)
def reach(s):
    seen={s};st=[s]
    while st:
        n=st.pop()
        for m in adj.get(n,()):
            if m not in seen:
                seen.add(m);st.append(m)
    return seen
print('stations',stations)
print('edges',edges)
found=None
for a,b in edges:
    adj[a].discard(b);adj[b].discard(a)
    base=reach(stations[0])
    orph=[s for s in stations if s not in base]
    adj.setdefault(a,set()).add(b);adj.setdefault(b,set()).add(a)
    if orph:
        found=(a,b);print('bridge:',a,b,'orphans',orph);break
if not found: print('no bridge')
for a,b in edges:
    if {a,b}!={found[0],found[1]}:
        print('normal pair:',a,b);break
EOF

