  }

  void SendTransition(uint8_t transition_id) {
    if (!dispatcher_change_state_cli_->service_is_ready()) return;
    auto req = std::make_shared<lifecycle_msgs::srv::ChangeState::Request>();
    req->transition.id = transition_id;
