TEST(TopologyOverlaySerializeTest, RejectsMissingBaseHash) {
  std::string message;
  const std::string text = "blocked_edges:\n  - from: \"a\"\n    to: \"b\"\n";
  EXPECT_FALSE(DeserializeTopologyOverlay(text, &message).has_value());
  EXPECT_TRUE(message.find("base_map_hash") != std::string::npos) << message;
}

// 在线提交路径（require_base_hash=false）：操作员只写管制清单即可，
// 基线哈希由提交管线盖章。这是两个模式**唯一**的差别 —— 其它严格性必须一致。
TEST(TopologyOverlaySerializeTest, OnlineModeAcceptsTextWithoutBaseHash) {
  std::string message;
  const std::string text =
      "blocked_edges:\n"
      "  - from: \"a\"\n"
      "    to: \"b\"\n"
      "    reason: \"water main\"\n"
      "    operator_id: \"op\"\n";
  const auto parsed = DeserializeTopologyOverlay(text, &message, false);
  ASSERT_TRUE(parsed.has_value()) << message;
  EXPECT_TRUE(parsed->base_map_hash.empty());
  ASSERT_EQ(parsed->blocked_edges.size(), 1u);
  EXPECT_EQ(parsed->blocked_edges.front().reason, "water main");
}

// 放宽的只有 base_map_hash；未知键在在线模式下仍然必须失败，
// 否则"写错的字段"会在控制台上看起来生效了。
//
// 报错文案取决于位置：出现在条目**内部**时属于"未知条目字段"，出现在顶层
// （即不在任何条目里）才是"未知顶层键"。两个位置都必须被拒 —— 分开断言，
// 免得把"位置不同"误读成"严格性不同"。
TEST(TopologyOverlaySerializeTest, OnlineModeStillRejectsUnknownKeys) {
  std::string message;
  const std::string inside_entry =
      "blocked_edges:\n  - from: \"a\"\n    to: \"b\"\n    bogus_key: 1\n";
  EXPECT_FALSE(DeserializeTopologyOverlay(inside_entry, &message, false).has_value());
  EXPECT_TRUE(message.find("unknown field inside edge entry") != std::string::npos) << message;

  const std::string at_top_level = "bogus_key: 1\nblocked_edges:\n  - from: \"a\"\n    to: \"b\"\n";
  EXPECT_FALSE(DeserializeTopologyOverlay(at_top_level, &message, false).has_value());
  EXPECT_TRUE(message.find("unknown top-level key") != std::string::npos) << message;
}

TEST(TopologyOverlaySerializeTest, AcceptsCommentsAndBlankLines) {

