   // readiness：逐组件聚合
   const auto probes = CollectComponentProbes();
   const auto verdict = EvaluateReadiness(probes);
   resp.body = RenderReadinessJson(verdict);
   if (!verdict.ready) {
     resp.status = "503 Service Unavailable";
   }

