  if (acc > static_cast<unsigned long long>(kMaxRequestBytes)) {
    if (out != nullptr) {
      *out = 0;  // 不返回被截断的巨值，调用方只按状态码处置
    }
    return ContentLengthStatus::kTooLarge;
  }
  if (out != nullptr) {
    *out = static_cast<std::size_t>(acc);
  }
  return ContentLengthStatus::kOk;
}

