188	bool WriteAll(int fd, const std::string& data) {
189	  std::size_t sent = 0;
190	  while (sent < data.size()) {
191	    const ssize_t n = ::send(fd, data.data() + sent, data.size() - sent, MSG_NOSIGNAL);
192	    if (n > 0) {
