      // 用 RecordLoss 会把解码噪声当成链路中断，几帧之内就把后端降级到 mock。
      backend_ctrl_->RecordCrcError();
    }
    if (invalid > 0) {
      binary_stream_.ClearInvalidFrameCount();
    }
    return binary_stream_.DrainPackets();
  }
  text_stream_.Append(data);
  return text_stream_.DrainPackets();
}

